const e=[{id:"sv-1-061",phase:1,topic:"1.1.1",qtype:"calculation",difficulty:2,stem:"A cloud-backup service logs **1,350 DPMO** (long-term data). Using the conventional **1.5σ shift**, what **sigma level** should be reported?",options:["3.0σ","3.2σ","4.5σ","6.0σ"],answer:2,hint:"Long-term yield = 1 − DPMO ÷ 10⁶; Z_LT is the one-tailed Z for that yield; sigma level = Z_LT + 1.5.",steps:[{title:"Write what is given",body:"$DPMO = 1350$ (long-term)."},{title:"Pick the formula",body:"$$\\text{Yield}_{LT}=1-\\dfrac{DPMO}{10^{6}}$$ and $$\\text{Sigma level}=Z_{LT}+1.5$$"},{title:"Substitute",body:"$$\\text{Yield}_{LT}=1-\\dfrac{1350}{1{,}000{,}000}=1-0.00135=0.99865$$"},{title:"Calculate",body:"The one-tailed Z with 0.99865 to its left is $Z_{LT}=3.00$. $$\\text{Sigma level}=3.00+1.5=4.5$$"},{title:"Decide",body:"The sigma table agrees: 4.5σ ↔ 1,350 DPMO. Report **4.5σ**."}],final:"Z_LT = 3.0 → sigma level = 4.5σ → answer **C**",whyWrong:["3.0σ is Z long-term only — the 1.5σ shift was not added.","3.2σ splits the defect rate over two tails (Z for 0.000675); defects against one limit use one tail, and the shift is still missing.","","6.0σ adds the 1.5σ shift twice (3.0 + 1.5 + 1.5)."],trap:"The shift is added once, to a one-tailed long-term Z.",bookRef:"Book p. 223"},{id:"sv-1-062",phase:1,topic:"1.1.1",qtype:"calculation",difficulty:3,stem:"An e-billing process runs at **4.0σ** (short-term, with the usual 1.5σ shift). Next month it will produce **50,000** e-bills, each with **4** defect opportunities. About how many **defects** should the team expect?",options:["6","311","1,242","2,484"],answer:2,hint:"DPMO at a sigma level = [1 − Φ(sigma − 1.5)] × 10⁶; expected defects = DPMO × total opportunities ÷ 10⁶.",steps:[{title:"Write what is given",body:"Sigma level = 4.0; $U = 50{,}000$; $O = 4$."},{title:"Find the DPMO",body:"$Z_{LT}=4.0-1.5=2.5$, and $1-\\Phi(2.5)=0.00621$. $$DPMO=0.00621\\times 10^{6}=6{,}210$$"},{title:"Count the opportunities",body:"$$TOP=U\\times O=50{,}000\\times 4=200{,}000$$"},{title:"Calculate expected defects",body:"$$\\text{Defects}=\\dfrac{DPMO\\times TOP}{10^{6}}=\\dfrac{6210\\times 200{,}000}{1{,}000{,}000}=1{,}242$$"},{title:"Decide",body:"Expect about **1,242** defects next month."}],final:"6,210 DPMO × 200,000 opportunities ≈ 1,242 defects → answer **C**",whyWrong:["6 ignores the 1.5σ shift (uses Z = 4.0, about 31.7 DPMO).","311 applies the DPMO to the 50,000 bills instead of the 200,000 opportunities.","","2,484 doubles the tail area as if defects fell on both sides; the sigma table is one-tailed."],bookRef:"Book p. 223"},{id:"sv-1-063",phase:1,topic:"1.1.1",qtype:"output",difficulty:2,stem:`A capability study of number-port completion time (USL = 24 h, long-term data) gives:

\`\`\`
Process Capability Report for PortTime

Overall Capability
Pp          *
PPL         *
PPU      0.95
Ppk      0.95
Z.Bench  2.85
PPM > USL  2186
\`\`\`

Using the conventional 1.5σ shift, what **sigma level** should the team quote?`,options:["1.35σ","2.45σ","2.85σ","4.35σ"],answer:3,hint:"Overall (long-term) Z.Bench is a Z_LT; sigma level = Z_LT + 1.5.",steps:[{title:"Locate",body:"Overall capability uses long-term variation, so **Z.Bench = 2.85** is a long-term Z."},{title:"Pick the rule",body:"$$\\text{Sigma level}=Z_{LT}+1.5$$"},{title:"Calculate",body:"$$\\text{Sigma level}=2.85+1.5=4.35$$ Check: $Ppk\\times 3=0.95\\times 3=2.85$, the same Z."},{title:"Decide",body:"Quote about **4.35σ**."}],final:"Z.Bench 2.85 + 1.5 = 4.35σ → answer **D**",whyWrong:["1.35σ subtracts the shift instead of adding it to a long-term Z.","2.45σ adds 1.5 to the Ppk index, not to the Z value.","2.85σ is the long-term Z itself — the shift was not added.",""],bookRef:"Book p. 223"},{id:"sv-1-064",phase:1,topic:"1.1.2",qtype:"concept",difficulty:1,stem:"Which pioneer introduced the **control chart** in the 1920s, giving continuous improvement its first statistical tool for separating common-cause from special-cause variation?",options:["Walter Shewhart","Bill Smith","Jack Welch","Taiichi Ohno"],answer:0,hint:"Link each name to its contribution: control charts, Motorola Six Sigma, GE roll-out, Toyota Production System.",steps:[{title:"Key idea",body:"Walter **Shewhart** at Bell Labs developed the control chart (1924) and the Plan–Do–Check cycle that Deming later popularised."},{title:"Eliminate look-alikes",body:"Bill Smith shaped Six Sigma at Motorola in the 1980s; Jack Welch made it a GE-wide programme in the 1990s; Taiichi Ohno built the Toyota Production System."}],final:"Control charts → Walter Shewhart → answer **A**",whyWrong:["","Bill Smith is linked to the creation of Six Sigma at Motorola, about 60 years after the first control chart.","Jack Welch led the GE Six Sigma roll-out in the 1990s; he did not invent control charts.","Taiichi Ohno is the father of the Toyota Production System (Lean), not of the control chart."],bookRef:"Syllabus 1.1.2"},{id:"sv-1-065",phase:1,topic:"1.1.2",qtype:"true-false",difficulty:1,stem:"Lean Six Sigma joins two streams of continuous improvement: the Toyota-based Lean approach to waste and flow, and the Motorola-based Six Sigma approach to defects and variation. True or False?",options:["True","False"],answer:0,hint:"Recall where Lean and Six Sigma each began.",steps:[{title:"Key idea",body:"Lean grew from the Toyota Production System (waste, flow, pull). Six Sigma grew from Motorola in the 1980s (defects, variation, DMAIC)."},{title:"Apply",body:"Lean Six Sigma combines both, so the statement is **True**."}],final:"Statement is correct → answer **A** (True)",whyWrong:["","False would deny the dual origin; the syllabus itself describes DMAIC as established by Motorola, and Lean comes from Toyota."],bookRef:"Syllabus p. 2"},{id:"sv-1-066",phase:1,topic:"1.1.3",qtype:"concept",difficulty:2,stem:"Which deliverable is expected at the **Measure** tollgate rather than at the Define tollgate?",options:["A signed project charter with problem and goal statements","A high-level SIPOC showing process boundaries","A validated measurement system and a baseline of the primary metric","A list of customer needs translated into CTQs"],answer:2,hint:"Define says what and why; Measure proves the data can be trusted and states current performance.",steps:[{title:"Key idea",body:"The book’s Measure step is “Assess stability, capability and measurement systems” — the data must be trusted (MSA) and today’s performance quantified (baseline)."},{title:"Apply to the options",body:"The charter, SIPOC and CTQs are all Define outputs. Only the validated measurement system plus baseline belongs to Measure."}],final:"MSA + baseline is a Measure deliverable → answer **C**",whyWrong:["The signed charter is the core Define deliverable.","The high-level SIPOC is built in Define to agree scope and boundaries.","","Translating VOC into CTQs is Define work; Measure then measures those CTQs."],bookRef:"Book pp. 229–230"},{id:"sv-1-067",phase:1,topic:"1.1.3",qtype:"scenario",difficulty:2,stem:"At the Define tollgate, a Green Belt presents a charter, a SIPOC and a plan to “install a new ticket-routing tool next month”. The Champion refuses to sign off. What is the MOST likely reason?",options:["The team has jumped to a solution before measuring the problem or proving root causes","The SIPOC should have been replaced by a detailed Level 3 process map","A Define tollgate must already include a control plan","The charter cannot be signed until the improvement has been piloted"],answer:0,hint:"DMAIC deliverables arrive phase by phase; solutions are an Improve output.",steps:[{title:"Key idea",body:"Define frames the problem, goal, scope and team. Solutions are chosen in Improve, after Measure and Analyze have shown the vital few X’s."},{title:"Apply",body:"Announcing a tool in Define is “solution jumping”. The Champion should send the team back to frame the problem without a built-in answer."}],final:"Solution jumping in Define → answer **A**",whyWrong:["","Define works at a high level; detailed Level 3 maps come later and are not a Define gate requirement.","The control plan is a Control-phase deliverable.","The charter is signed at the start; a pilot happens in Improve."],bookRef:"Book p. 230"},{id:"sv-1-068",phase:1,topic:"1.1.3",qtype:"not-except",difficulty:1,stem:"All of the following are **Define-phase** deliverables EXCEPT:",options:["Project charter with business case","Estimate of the cost of poor quality","Control plan with a response plan","Identified project team and roles"],answer:2,hint:"Book roadmap for Define: identify problem area → set project focus → estimate COPQ → establish team.",steps:[{title:"Key idea",body:"The book’s DMAIC roadmap lists four Define steps: identify the problem area, determine the project focus, **estimate COPQ** and **establish the team**. The charter records them."},{title:"Find the intruder",body:"The **control plan** is produced in Control, when the solution is handed to the process owner."}],final:"Control plan = Control deliverable → answer **C**",whyWrong:["The charter with its business case is the main Define deliverable.","“Estimate COPQ” is a named Define step on the DMAIC roadmap.","","“Establish Team” is a named Define step on the DMAIC roadmap."],bookRef:"Book p. 230"},{id:"sv-1-069",phase:1,topic:"1.1.3",qtype:"sequence",difficulty:2,stem:`The book’s DMAIC roadmap lists four Define steps:

- **P** Establish team
- **Q** Determine appropriate project focus
- **R** Identify problem area
- **S** Estimate COPQ

In which order do they appear?`,options:["R → Q → S → P","Q → R → S → P","R → S → Q → P","P → R → Q → S"],answer:0,hint:"Broad problem first, then narrow the focus, then size it, then staff it.",steps:[{title:"Key idea",body:"The roadmap moves from broad to specific: **identify the problem area**, **narrow to a project focus**, **estimate COPQ** to size the prize, then **establish the team**."},{title:"Apply",body:"That is R → Q → S → P."}],final:"R → Q → S → P → answer **A**",whyWrong:["","You cannot narrow to a focus (Q) before a problem area (R) has been identified.","COPQ is estimated for the chosen focus, so Q comes before S.","The team is established last, once the focus and its size are known."],bookRef:"Book p. 230"},{id:"sv-1-070",phase:1,topic:"1.1.4",qtype:"table",difficulty:2,stem:`A team lists inputs (X’s) to fibre-installation success and classifies them as **C** (controllable), **N** (noise) or **S** (standard operating procedure):

| Input | Class |
|---|---|
| ONT firmware version loaded | C |
| Length of the customer’s drop cable | C |
| Technician follows the light-level test script | S |
| Rain on the day of the visit | N |

Which row is **misclassified**?`,options:["ONT firmware version loaded","Technician follows the light-level test script","Rain on the day of the visit","Length of the customer’s drop cable"],answer:3,hint:"Controllable = the team can set it; noise = it varies and the team cannot or will not control it; SOP = a procedure.",steps:[{title:"Key idea",body:"Inputs are controllable (we set them), procedural (SOP) or noise (they vary outside our control). Critical X’s must be controlled and measured."},{title:"Check each row",body:"Firmware is set by the operator (C). The test script is a procedure (S). Rain is noise (N). The **drop-cable length** depends on where the customer lives — the team cannot set it, so it is **noise**, not controllable."}],final:"Drop-cable length is noise, not controllable → answer **D**",whyWrong:["Firmware version is chosen and loaded by the operator, so C is correct.","Following a test script is a procedural (SOP) input, so S is correct.","Weather varies outside the team’s control, so N is correct.",""],bookRef:"Book pp. 113–114"},{id:"sv-1-071",phase:1,topic:"1.1.4",qtype:"concept",difficulty:1,stem:"In **Y = f(X)**, which description fits **Y**?",options:["An input that the team can set directly","The output or result, which depends on the inputs","A noise factor that cannot be controlled","The error term that the model cannot explain"],answer:1,hint:"Y is the dependent variable; X’s are the independent variables.",steps:[{title:"Key idea",body:"Y is the **output** (dependent, often a lagging result such as CSAT or SLA %). X’s are the inputs and process variables that drive it."},{title:"Eliminate",body:"Inputs and noise factors are X’s; the error term is the “e” in $Y = f(X) + e$."}],final:"Y = the output that depends on the X’s → answer **B**",whyWrong:["An input the team can set is a controllable X.","","A noise factor is an uncontrolled X, not the Y.","The unexplained part is the error term e in Y = f(X) + e."],bookRef:"Book p. 208"},{id:"sv-1-072",phase:1,topic:"1.1.4",qtype:"output",difficulty:3,stem:`A contact-centre team explores candidate X’s for customer satisfaction (CSAT) using **120** days of data:

\`\`\`
Correlation: CSAT, WaitTime, FCR, AgentTenure

              CSAT  WaitTime     FCR
WaitTime    -0.71
             0.000
FCR          0.58     -0.32
             0.000     0.004
AgentTenure  0.09      0.05    0.11
             0.412     0.588   0.231

Cell Contents: Pearson correlation
               P-Value
\`\`\`

Which statement is BEST supported in Y = f(X) terms?`,options:["CSAT is the strongest X because it correlates with two other variables","WaitTime is the weakest candidate X because its correlation is negative","WaitTime and FCR are candidate X’s for the Y (CSAT); AgentTenure shows no significant linear link in these data","AgentTenure has been proven to have no effect on CSAT in any situation"],answer:2,hint:"The Y is the outcome; strength is |r|, the sign is direction; p ≤ 0.05 means a significant linear link.",steps:[{title:"Locate",body:"CSAT is the outcome (Y). Against CSAT: WaitTime r = −0.71 (p = 0.000), FCR r = 0.58 (p = 0.000), AgentTenure r = 0.09 (p = 0.412)."},{title:"Apply the rule",body:"Strength is the size of r, not its sign. Both WaitTime and FCR are significant (p < 0.05) — good candidate X’s to carry into Measure/Analyze. AgentTenure is not significant here: we **fail to reject** “no linear correlation”."},{title:"Eliminate",body:"Failing to find a link is not proof of no effect, and correlation alone is not causation."}],final:"WaitTime and FCR are candidate X’s; AgentTenure not significant → answer **C**",whyWrong:["CSAT is the Y (the outcome), not an X.","|−0.71| is the strongest correlation in the table; a negative sign shows direction, not weakness.","","A p-value of 0.412 means we fail to reject; it never proves zero effect in every situation."],trap:"Judge strength by |r|; the minus sign only says “as wait goes up, CSAT goes down”.",bookRef:"Book pp. 240, 476"},{id:"sv-1-073",phase:1,topic:"1.1.4",qtype:"scenario",difficulty:2,stem:"An operator measures its managed-services vendor on **monthly P1 incident restoration within 4 hours**. The vendor team proposes to improve this result. Which of these is a **Y** rather than an X?",options:["Percentage of P1 incidents restored within 4 hours","Time taken to engage the on-call engineer","Accuracy of the monitoring alert that opens the incident","Availability of an up-to-date runbook for the failed service"],answer:0,hint:"Y = the result the customer or business sees; X’s = the process inputs and steps that drive it.",steps:[{title:"Key idea",body:"The SLA result is an output measure — a **Y**. Engagement time, alert accuracy and runbook availability are process drivers — **X’s**."},{title:"Apply",body:"Improving the Y means finding and controlling the X’s, not chasing the monthly percentage."}],final:"SLA restoration % is the Y → answer **A**",whyWrong:["","Engagement time is a process step that drives restoration time — an X.","Alert accuracy is an input to how fast the incident starts — an X.","Runbook availability is a procedural input — an X."],bookRef:"Book p. 208"},{id:"sv-1-074",phase:1,topic:"1.1.5",qtype:"scenario",difficulty:1,stem:"In a focus group, field technicians say: *“We lose an hour a day because job sheets arrive without the customer’s gate code.”* Which voice is this?",options:["Voice of the Customer","Voice of the Business","Voice of the Employee","Voice of the Process"],answer:2,hint:"Ask who is speaking: external customer, the business/finance, the people who do the work, or the process data itself.",steps:[{title:"Key idea",body:"VOE captures what employees experience doing the work — barriers, workarounds, frustrations."},{title:"Apply",body:"The technicians are describing their own working barrier, so it is **Voice of the Employee**."}],final:"Technicians describing their work barrier → VOE → answer **C**",whyWrong:["VOC comes from the external customer who receives the service, not the technicians.","VOB is the business view — profit, cost, compliance, strategy.","","Voice of the Process is what the process data show (e.g. control charts), not a spoken complaint."],bookRef:"Book p. 590"},{id:"sv-1-075",phase:1,topic:"1.1.5",qtype:"concept",difficulty:1,stem:"A team checks each customer requirement with **RUMBA** before turning it into a CTQ. What does RUMBA test?",options:["Whether the requirement is Realistic, Understandable, Measurable, Believable and Attainable","Whether the requirement is Reliable, Usable, Marketable, Budgeted and Approved","Whether the requirement is Ranked, Unique, Monitored, Benchmarked and Audited","Whether the requirement is Relevant, Urgent, Mandatory, Basic and Advanced"],answer:0,hint:"RUMBA = five quality tests on a requirement.",steps:[{title:"Key idea",body:"RUMBA validates customer requirements: **R**ealistic, **U**nderstandable, **M**easurable, **B**elievable, **A**ttainable."},{title:"Apply",body:"A requirement that fails, for example one that cannot be measured, must be clarified with the customer before it becomes a CTQ."}],final:"RUMBA = Realistic, Understandable, Measurable, Believable, Attainable → answer **A**",whyWrong:["","These words describe product or budget approval, not the RUMBA test.","These are monitoring words; RUMBA does not include ranking or auditing.","This mixes Kano-style categories with urgency; it is not RUMBA."],bookRef:"Book p. 112"},{id:"sv-1-076",phase:1,topic:"1.1.5",qtype:"output",difficulty:2,stem:`A post-call survey collected **500** free-text comments, coded by theme:

\`\`\`
Tally for Discrete Variables: Comment theme

Theme                Count  Percent
Long wait in IVR       212    42.40
Repeat my details      138    27.60
Bill confusing          74    14.80
Rude agent              40     8.00
App crashes             36     7.20
     N=                500
\`\`\`

What is the BEST next step for the Green Belt?`,options:["Hire more agents straight away, because long waits are the top theme","Focus on “Rude agent” first, because behaviour issues are the most serious","Use 42.4% as the project’s CTQ target","Translate the top theme into a measurable CTQ, e.g. time from IVR entry to agent answer, with a customer-based limit"],answer:3,hint:"VOC is vague; a CTQ is a measurable characteristic with an operational definition and a limit.",steps:[{title:"Locate",body:"“Long wait in IVR” is the largest theme (42.4%), followed by “Repeat my details” (27.6%)."},{title:"Apply",body:"Define turns the voice into a **CTQ**: a measurable characteristic (time from IVR entry to agent answer) with a limit set from the customer’s view (e.g. ≤ 60 s)."},{title:"Eliminate",body:"Hiring is a solution (Improve); the 42.4% share is not a CTQ; theme counts do not support putting the 8% theme first."}],final:"Convert the top VOC theme into a measurable CTQ → answer **D**",whyWrong:["Hiring agents is a solution chosen before measuring or analysing causes.","The data show the rude-agent theme is small (8%); severity was not measured here.","A share of comments is not a CTQ; a CTQ measures the service characteristic itself.",""],bookRef:"Book p. 112"},{id:"sv-1-077",phase:1,topic:"1.1.6",qtype:"scenario",difficulty:2,stem:"A Green Belt is unsure whether to use a p chart or a u chart for her baseline data and asks for expert statistical coaching. In a typical deployment, who should provide it?",options:["Executive sponsor","Process owner","Finance representative","Master Black Belt (or a Black Belt mentor)"],answer:3,hint:"Teaching and mentoring Belts is a specific role.",steps:[{title:"Key idea",body:"The **Master Black Belt** teaches and mentors Black and Green Belts and is the deployment’s statistical expert; a Black Belt often mentors Green Belts too."},{title:"Eliminate",body:"Sponsors and process owners give direction and ownership; Finance validates savings."}],final:"Statistical coaching → Master Black Belt / Black Belt mentor → answer **D**",whyWrong:["The executive sponsor sets direction and resources, not statistical coaching.","The process owner owns the process and its results, not tool selection.","Finance validates hard and soft savings, not chart choice.",""],bookRef:"Book p. 586"},{id:"sv-1-078",phase:1,topic:"1.1.6",qtype:"concept",difficulty:1,stem:"Which role provides an **independent evaluation of hard and soft savings** claimed by a project?",options:["Finance representative","Green Belt","Champion","Process owner"],answer:0,hint:"The book glossary gives one role exactly this job.",steps:[{title:"Key idea",body:"The book glossary defines the **Finance representative** as the person who gives independent evaluation of hard and/or soft savings."},{title:"Apply",body:"Independence matters: the people who led or sponsored the project should not certify its own benefits."}],final:"Finance representative → answer **A**",whyWrong:["","The Green Belt estimates benefits but is not independent of the project.","The Champion is accountable for results, so is not an independent checker.","The process owner keeps the gains but does not certify savings."],bookRef:"Book p. 585"},{id:"sv-1-079",phase:1,topic:"1.1.6",qtype:"not-except",difficulty:2,stem:"Which of the following is NOT normally a responsibility of the **Champion**?",options:["Selecting and scoping projects that support business goals","Removing barriers the team cannot remove itself","Chairing tollgate reviews","Collecting the day-to-day process data for the baseline"],answer:3,hint:"Champion = recognises, defines, assigns and supports projects; accountable for results.",steps:[{title:"Key idea",body:"The Champion **recognises, defines, assigns and supports** projects, removes barriers and chairs tollgates."},{title:"Find the intruder",body:"Collecting baseline data is hands-on project work done by the Belt and team members."}],final:"Data collection is team work, not the Champion’s → answer **D**",whyWrong:["Selecting and scoping projects is a core Champion duty.","Removing barriers is a core Champion duty.","Chairing tollgates is a core Champion duty.",""],bookRef:"Book p. 584"},{id:"sv-1-080",phase:1,topic:"1.1.6",qtype:"true-false",difficulty:1,stem:"A Green Belt is typically a full-time improvement specialist who leads large cross-functional projects and mentors Black Belts. True or False?",options:["True","False"],answer:1,hint:"Compare part-time vs full-time roles and who mentors whom.",steps:[{title:"Key idea",body:"A Green Belt works **part-time** on smaller projects in their own area and supports Black Belt projects. The Black Belt is full-time; the Master Black Belt mentors Black Belts."},{title:"Apply",body:"The statement describes a Black Belt / Master Black Belt mix, so it is **False**."}],final:"Green Belt = part-time, smaller local projects → answer **B** (False)",whyWrong:["True would make the Green Belt a full-time mentor of Black Belts — that is the Master Black Belt’s role.",""],bookRef:"Book p. 586"},{id:"sv-1-081",phase:1,topic:"1.2.1",qtype:"concept",difficulty:1,stem:"Which definition of a **process** is the BEST fit for Lean Six Sigma work?",options:["A department and the people who report to its manager","A blending of inputs through a repeatable series of steps to produce an output for a customer","A software system that records transactions","A written procedure stored in the quality manual"],answer:1,hint:"Think inputs → steps → outputs → customer, regardless of department lines.",steps:[{title:"Key idea",body:"The book describes a process as a **blending of inputs to produce a desired output**. It crosses departments and serves a customer."},{title:"Eliminate",body:"A department is an organisation unit, a system is a tool used inside a process, and a procedure documents a process but is not the process itself."}],final:"Inputs blended through steps into an output for a customer → answer **B**",whyWrong:["A department is an organisational unit; most processes cross several departments.","","A software system supports a process step; it is not the process.","A procedure describes how a process should run; the process is the actual work."],bookRef:"Book p. 99"},{id:"sv-1-082",phase:1,topic:"1.2.1",qtype:"scenario",difficulty:2,stem:"In Define, a Green Belt shows her Champion a process map of mobile-number porting with **46** boxes, decision diamonds and system screens. The Champion says it is “the wrong map for now”. What should she produce instead?",options:["A detailed Level 3 map with yields and cycle times for every step","A Level 1 (macro) map with about four to seven major steps, plus one step before and after the problem area","A spaghetti diagram of how staff walk around the office","A value stream map of the future state"],answer:1,hint:"Define needs the management view of scope, not the improvement-level detail.",steps:[{title:"Key idea",body:"Process maps come in levels. **Level 1** (macro, management view) shows the big picture and scope — the right view for Define and for status reports."},{title:"Apply",body:"A 46-box map is Level 2/3 detail, used later in Measure and Analyze. The book also advises adding at least one step in front of and behind the problem area."}],final:"Define needs a Level 1 macro map → answer **B**",whyWrong:["A Level 3 map is the detailed improvement view used later, not the Define scope view.","","A spaghetti diagram shows physical movement, not process scope.","A future-state map is designed in Improve, after the current state is understood."],bookRef:"Book pp. 102–103, 108"},{id:"sv-1-083",phase:1,topic:"1.2.1",qtype:"concept",difficulty:3,stem:"When drawing a macro process map, the book advises adding **at least one step in front of and one step behind** the area believed to contain the problem. Why?",options:["To make the map look complete for management presentations","To make sure every department is represented on the team","Because the cause may sit upstream, or the effect may show up downstream, of where the problem is first seen","Because a Level 1 map must always have exactly seven steps"],answer:2,hint:"Problems are often caused or detected outside the step where they are noticed.",steps:[{title:"Key idea",body:"The symptom is often seen in one step while its cause is upstream (e.g. bad input data) or its impact is downstream (e.g. rework later). A wider boundary avoids scoping out the real X."},{title:"Eliminate",body:"It is not about looks, team membership or a fixed step count (Level 1 maps usually have about four to seven steps)."}],final:"Causes and effects can sit just outside the problem area → answer **C**",whyWrong:["The rule protects the analysis, not the presentation.","Team make-up is decided separately; map boundaries are about the process flow.","","There is no fixed count; four to seven is a guideline, not a rule."],bookRef:"Book p. 108"},{id:"sv-1-084",phase:1,topic:"1.2.1",qtype:"scenario",difficulty:1,stem:"In a SIPOC for **monthly bill production**, the billing team sends a file of disputed bills to the collections team, which uses it to pause dunning letters. How should the collections team be shown?",options:["As a supplier, because it supplies the dunning letters","As an internal customer that receives an output of the process","As an input, because it is part of the business","It should be left off, because only paying subscribers are customers"],answer:1,hint:"A customer is anyone who receives an output of the process — inside or outside the company.",steps:[{title:"Key idea",body:"Customers in a SIPOC can be **external** (subscribers) or **internal** (other teams that receive an output)."},{title:"Apply",body:"Collections receives the disputed-bills file — an output — so it is an **internal customer**."}],final:"Collections receives an output → internal customer → answer **B**",whyWrong:["Dunning letters belong to a different process; in this SIPOC collections receives, it does not supply.","","A team is not an input; inputs are the materials, data and information the process uses.","Leaving out internal customers hides real requirements on the output."],bookRef:"Book p. 111"},{id:"sv-1-085",phase:1,topic:"1.2.1",qtype:"sequence",difficulty:2,stem:`The book gives a checklist for creating a **Level 1** process map:

- **P** Walk through and write down the major steps
- **Q** Identify the beginning and ending steps
- **R** Give the process a generic name
- **S** Describe the process purpose (operational description)

In which order are they done?`,options:["Q → R → S → P","R → Q → S → P","R → S → P → Q","S → R → Q → P"],answer:1,hint:"Name it, bound it, state why it exists, then list what happens inside.",steps:[{title:"Key idea",body:"The book’s order is: (1) generic **name**, (2) **beginning and end** points, (3) primary **purpose**, (4) major **steps**, then draw them with standard symbols."},{title:"Apply",body:"That is R → Q → S → P."}],final:"Name → boundaries → purpose → major steps → answer **B**",whyWrong:["The process is named before its boundaries are set.","","Steps cannot be listed before the start and end points are known.","The purpose describes a named, bounded process, so it comes after R and Q."],bookRef:"Book pp. 108–109"},{id:"sv-1-086",phase:1,topic:"1.2.1",qtype:"true-false",difficulty:2,stem:"The process as people **think** it works, as it **actually** works, and as it **should** work are usually the same, so a Green Belt can map the process from the written procedure alone. True or False?",options:["True","False"],answer:1,hint:"Recall the three views of a process.",steps:[{title:"Key idea",body:"The book separates three views: what you **think** it is, what it **actually** is and what it **should** be. The actual process often holds hidden rework loops."},{title:"Apply",body:"Mapping only from the procedure misses the hidden factory, so the statement is **False**."}],final:"The three views usually differ → answer **B** (False)",whyWrong:["True ignores the hidden operations that only appear when the actual process is walked and observed.",""],bookRef:"Book p. 100"},{id:"sv-1-087",phase:1,topic:"1.2.2",qtype:"table",difficulty:2,stem:`A CTQ tree for the need *“A bill I can trust”* has these drivers and CTQs:

| Driver | Proposed CTQ |
|---|---|
| Accuracy | Bills with a charge error ≤ 0.5% per cycle |
| Timeliness | Bill issued ≤ 2 working days after cycle close |
| Clarity | Bill is easy for customers to read |
| Payment | Payment posted to the account ≤ 24 h after receipt |

Which proposed CTQ is **not** properly formed?`,options:["Accuracy","Timeliness","Clarity","Payment"],answer:2,hint:"A CTQ must be measurable, with an operational definition and a limit.",steps:[{title:"Key idea",body:"A CTQ is a **measurable** characteristic with a clear limit, so performance against it can be counted."},{title:"Check each row",body:"Accuracy, timeliness and payment all have a measure and a limit. “Easy to read” is still a need — it has no measure or limit (e.g. “% of customers who can find the amount due within 30 s ≥ 95%”)."}],final:"Clarity CTQ has no measure or limit → answer **C**",whyWrong:["Accuracy has a measure (% bills with charge errors) and a limit (≤ 0.5%).","Timeliness has a measure (days after cycle close) and a limit (≤ 2).","","Payment posting has a measure (hours) and a limit (≤ 24 h)."],bookRef:"Book pp. 112, 509"},{id:"sv-1-088",phase:1,topic:"1.2.2",qtype:"output",difficulty:2,stem:`The CTQ for business fibre is “installation completed within **5 working days** of order acceptance”. A Tally of last quarter’s orders gives:

\`\`\`
Tally for Discrete Variables: Within5Days

Within5Days  Count  Percent
No             152    10.00
Yes           1368    90.00
     N=       1520
\`\`\`

Treating each order as one opportunity, which statement correctly expresses the baseline?`,options:["152 DPMO, because 152 orders failed the CTQ","11.1% defective, because 152 late orders were compared with 1,368 on-time orders","10.0% defective against the CTQ, which is 100,000 DPMO","90.0% defective, because 1,368 orders were counted"],answer:2,hint:"% defective = units failing the CTQ ÷ all units; DPMO with one opportunity per unit = proportion × 10⁶.",steps:[{title:"Locate",body:"Defects against the CTQ (“No”) = 152; all orders N = 1,520."},{title:"Calculate",body:"$$p=\\dfrac{152}{1520}=0.10=10.0\\%$$ $$DPMO=\\dfrac{152}{1520\\times 1}\\times 10^{6}=100{,}000$$"},{title:"Decide",body:"The baseline is **10% late**, i.e. 100,000 DPMO."}],final:"10% of orders miss the CTQ = 100,000 DPMO → answer **C**",whyWrong:["152 is a count, not a rate per million opportunities.","Dividing by the good orders (1,368) instead of all orders (1,520) inflates the rate.","","90% is the share that met the CTQ, not the defect rate."],bookRef:"Book p. 585"},{id:"sv-1-089",phase:1,topic:"1.2.2",qtype:"concept",difficulty:1,stem:"In the **Kano model**, a feature that customers do not expect, but which delights them when present — for example a proactive SMS that a technician is 10 minutes away — is a:",options:["Basic (must-be) requirement","Delighter (attractive) requirement","Performance (one-dimensional) requirement","Indifferent requirement"],answer:1,hint:"Basic = expected, only noticed when missing; performance = more is better; delighter = unexpected surprise.",steps:[{title:"Key idea",body:"Delighters are unspoken and unexpected; their absence causes no dissatisfaction, but their presence raises satisfaction sharply."},{title:"Apply",body:"Customers do not ask for a “10 minutes away” SMS, but they love it — a **delighter**. Over time delighters tend to become basic expectations."}],final:"Unexpected feature that pleases → delighter → answer **B**",whyWrong:["A basic requirement is expected; its absence causes complaints, its presence goes unnoticed.","","A performance requirement scales linearly (e.g. faster speed = happier); customers ask for it.","An indifferent feature makes no difference to satisfaction, which contradicts “delights them”."],bookRef:"Syllabus 1.2.2"},{id:"sv-1-090",phase:1,topic:"1.2.2",qtype:"scenario",difficulty:1,stem:"Enterprise customers say: *“When the network is down, tell us what is happening.”* Which is the BEST CTQ to derive from this need?",options:["Customers feel well informed during outages","Time from P1 incident creation to first customer notification ≤ 15 minutes","Install a new outage-notification platform","Reduce the number of network outages"],answer:1,hint:"A CTQ is measurable, has a limit and reflects the customer’s need, not a solution.",steps:[{title:"Key idea",body:"Need → driver (timely updates) → **CTQ** (a measurable characteristic with a limit)."},{title:"Apply",body:"“Time from incident creation to first notification ≤ 15 minutes” is measurable, has a limit and serves the stated need."},{title:"Eliminate",body:"“Feel informed” is still a need; a platform is a solution; fewer outages is a different need."}],final:"Measurable notification-time CTQ → answer **B**",whyWrong:["This restates the need as a feeling; it has no measure or limit.","","This is a solution, not a requirement.","Customers asked to be informed, not for fewer outages; this changes the problem."],bookRef:"Book p. 509"},{id:"sv-1-091",phase:1,topic:"1.2.2",qtype:"concept",difficulty:1,stem:"Why does every CTQ need an **operational definition**?",options:["So that the CTQ can be shown on the project charter","So that different people measure and classify the characteristic the same way","So that the CTQ automatically becomes a Kano delighter","So that the specification limits can be widened if needed"],answer:1,hint:"Think about two sites measuring the same thing differently.",steps:[{title:"Key idea",body:"An operational definition says exactly **what** to measure, **how**, and what counts as a defect (e.g. when the clock starts and stops)."},{title:"Apply",body:"Without it, two teams can report different numbers for the same process, and the baseline cannot be trusted."}],final:"Consistent measurement and classification → answer **B**",whyWrong:["Appearing on the charter is not the reason; consistency of measurement is.","","Kano category depends on customer reaction, not on how a CTQ is defined.","Specifications come from the customer; an operational definition does not loosen them."],bookRef:"Book p. 109"},{id:"sv-1-092",phase:1,topic:"1.2.2",qtype:"scenario",difficulty:3,stem:"A corporate client requires a **site survey report within 1 hour ± 5 minutes** of the engineer leaving the site — earlier reports arrive before lab results are attached, later reports delay planning. How should the CTQ’s specification limits be written?",options:["USL = 60 min only, because early reports are always good","LSL = 55 min and USL = 65 min, target 60 min","LSL = 0 min and USL = 65 min","Target 60 min with no limits, because the client gave a target"],answer:1,hint:"A target with a ± tolerance gives two limits: target − tolerance and target + tolerance.",steps:[{title:"Write what is given",body:"Target = 60 min; tolerance = ± 5 min; both early and late are defects."},{title:"Set the limits",body:"$$LSL=60-5=55\\text{ min}\\qquad USL=60+5=65\\text{ min}$$"},{title:"Decide",body:"This is a **two-sided** CTQ: a report outside 55–65 minutes is a defect."}],final:"LSL 55, USL 65, target 60 → answer **B**",whyWrong:["The client said early reports are a problem too, so a one-sided USL is wrong — and it ignores the + 5 min tolerance.","","LSL = 0 treats early reports as good, ignoring the − 5 min tolerance.","A target alone cannot classify defects; the ± 5 min tolerance must become limits."],bookRef:"Book p. 112"},{id:"sv-1-093",phase:1,topic:"1.2.3",qtype:"calculation",difficulty:2,stem:`A data-centre operations unit records these annual costs (OMR):

- Re-imaging servers after failed builds: **28,000**
- Overtime to re-run failed batch jobs: **17,000**
- Service credits paid to enterprise clients after outages: **54,000**
- Emergency engineer call-outs to client sites after failures: **21,000**
- Monthly backup-restore tests: **12,000**
- Change-management training: **9,000**

Using COPQ = internal failure + external failure, what is the **COPQ**?`,options:["OMR 45,000","OMR 120,000","OMR 132,000","OMR 141,000"],answer:1,hint:"COPQ = internal failure (found before the customer) + external failure (found by or affecting the customer). Prevention and appraisal are excluded.",steps:[{title:"Write what is given",body:"Internal failure: re-imaging 28,000; batch re-runs 17,000. External failure: service credits 54,000; call-outs 21,000. Appraisal: restore tests 12,000. Prevention: training 9,000."},{title:"Pick the formula",body:"$$COPQ=C_{IF}+C_{EF}$$"},{title:"Substitute and calculate",body:"$$COPQ=(28{,}000+17{,}000)+(54{,}000+21{,}000)=45{,}000+75{,}000=120{,}000$$"},{title:"Interpret",body:"External failure is the larger part: $$\\dfrac{75{,}000}{120{,}000}\\times 100=62.5\\%$$ OMR 120,000 is the size of the prize. Restore tests (appraisal) and training (prevention) are good-quality costs, not failure costs."}],final:"COPQ = OMR 120,000 → answer **B**",whyWrong:["45,000 counts internal failure only and leaves out the external failures.","","132,000 adds the appraisal cost (backup-restore tests) to COPQ.","141,000 adds every cost, including prevention and appraisal — that is total cost of quality."],bookRef:"Book pp. 230, 584"},{id:"sv-1-094",phase:1,topic:"1.2.3",qtype:"calculation",difficulty:3,stem:"A provisioning team handles **25,000** orders a year. **12%** of orders need rework, each taking **18 minutes** of staff time. Fully loaded staff cost is **OMR 6 per hour**. What is the annual cost of this **hidden factory**?",options:["OMR 5,400","OMR 39,600","OMR 45,000","OMR 324,000"],answer:0,hint:"Hidden-factory cost = units reworked × rework time (in hours) × cost per hour.",steps:[{title:"Write what is given",body:"Orders = 25,000; rework rate = 0.12; rework time = 18 min; rate = OMR 6 per hour."},{title:"Count the reworked orders",body:"$$25{,}000\\times 0.12=3{,}000$$"},{title:"Convert minutes to hours",body:"$$\\dfrac{18}{60}=0.3\\text{ h}$$"},{title:"Calculate",body:"$$\\text{Cost}=3{,}000\\times 0.3\\times 6=5{,}400$$"},{title:"Interpret",body:"About **OMR 5,400** a year of internal failure cost hidden inside normal work."}],final:"Hidden-factory cost = OMR 5,400 → answer **A**",whyWrong:["","39,600 applies the rework time to the 88% of orders that did not need rework.","45,000 applies the rework time to all 25,000 orders instead of the 12% reworked.","324,000 multiplies minutes by an hourly rate (no conversion to hours)."],trap:"Match the units: minutes × OMR per hour needs a ÷ 60.",bookRef:"Book p. 586"},{id:"sv-1-095",phase:1,topic:"1.2.3",qtype:"calculation",difficulty:3,stem:"A billing unit’s annual quality costs are: prevention **OMR 10,000**, appraisal **OMR 40,000**, internal failure **OMR 90,000**, external failure **OMR 160,000**. An error-proofing programme adds **OMR 30,000** of prevention per year. Afterwards internal failure falls to **OMR 60,000** and external failure to **OMR 100,000**; appraisal is unchanged. How does the **total cost of quality** change?",options:["Falls by OMR 160,000","Falls by OMR 90,000","Falls by OMR 60,000","Rises by OMR 30,000"],answer:2,hint:"COQ = prevention + appraisal + internal failure + external failure; compare before and after.",steps:[{title:"Pick the formula",body:"$$COQ=C_{P}+C_{A}+C_{IF}+C_{EF}$$"},{title:"Before",body:"$$COQ_{before}=10{,}000+40{,}000+90{,}000+160{,}000=300{,}000$$"},{title:"After",body:"$$COQ_{after}=40{,}000+40{,}000+60{,}000+100{,}000=240{,}000$$"},{title:"Calculate the change",body:"$$\\Delta COQ=240{,}000-300{,}000=-60{,}000$$"},{title:"Interpret",body:"Each extra OMR of prevention removed $$\\dfrac{90{,}000}{30{,}000}=3$$ OMR of failure cost: a **net fall of OMR 60,000**."}],final:"Total COQ falls by OMR 60,000 → answer **C**",whyWrong:["160,000 is the new COPQ (60,000 + 100,000), reported as if it were the change.","90,000 is the fall in failure cost only; the extra 30,000 prevention spend was ignored.","","+30,000 counts the new prevention spend but ignores the failure-cost reduction it bought."],bookRef:"Book p. 584"},{id:"sv-1-096",phase:1,topic:"1.2.3",qtype:"output",difficulty:2,stem:`A Green Belt totals one year of quality-related costs by category:

\`\`\`
Tabulated Statistics: Category; Sum of Cost (OMR)

Category            Count       Sum
Prevention             14    18,000
Appraisal              37    42,000
Internal failure      212    96,000
External failure      158   144,000
All                   421   300,000
\`\`\`

What percentage of the **total cost of quality** is COPQ?`,options:["32%","48%","60%","80%"],answer:3,hint:"COPQ = internal + external failure; express it as a share of the “All” total.",steps:[{title:"Locate",body:"Internal failure 96,000; external failure 144,000; All = 300,000."},{title:"Pick the formula",body:"$$\\%COPQ=\\dfrac{C_{IF}+C_{EF}}{COQ}\\times 100$$"},{title:"Calculate",body:"$$\\%COPQ=\\dfrac{96{,}000+144{,}000}{300{,}000}\\times 100=\\dfrac{240{,}000}{300{,}000}\\times 100=80\\%$$"},{title:"Interpret",body:"Only 20% is spent on prevention and appraisal — a classic sign that more prevention would pay back."}],final:"COPQ = 80% of COQ → answer **D**",whyWrong:["32% is internal failure alone (96,000 of 300,000).","48% is external failure alone (144,000 of 300,000).","60% is external failure as a share of COPQ (144,000 of 240,000), a different question.",""],bookRef:"Book p. 584"},{id:"sv-1-097",phase:1,topic:"1.2.3",qtype:"table",difficulty:1,stem:`A mobile operator lists these annual costs:

| Cost item | OMR |
|---|---|
| Incoming inspection of SIM card batches | 11,000 |
| Call-quality monitoring of agents | 26,000 |
| Audit of each billing run before release | 15,000 |
| Supplier qualification visits | 8,000 |
| Re-issuing bills found wrong after dispatch | 19,000 |
| Error-proofing the online order form | 7,000 |

What is the total **appraisal** cost?`,options:["OMR 15,000","OMR 52,000","OMR 60,000","OMR 71,000"],answer:1,hint:"Appraisal = inspecting, testing, auditing and monitoring to find defects.",steps:[{title:"Classify",body:"Appraisal: SIM inspection 11,000; call monitoring 26,000; billing-run audit 15,000. Prevention: supplier qualification 8,000; error-proofing 7,000. External failure: re-issued bills 19,000."},{title:"Calculate",body:"$$C_{A}=11{,}000+26{,}000+15{,}000=52{,}000$$"}],final:"Appraisal = OMR 52,000 → answer **B**",whyWrong:["15,000 is the prevention total (8,000 + 7,000), not appraisal.","","60,000 counts supplier qualification as appraisal; it prevents defects, so it is prevention.","71,000 counts the re-issued bills as appraisal; fixing a defect after dispatch is external failure."],bookRef:"Book p. 584"},{id:"sv-1-098",phase:1,topic:"1.2.3",qtype:"not-except",difficulty:1,stem:"All of the following are **external failure** costs EXCEPT:",options:["Bill credits paid for missed installation appointments","Handling calls from customers about wrong bills","Re-running a failed billing job before bills are sent","Revenue lost when an angry customer ports out"],answer:2,hint:"Internal failure is found before the customer receives the output; external failure after.",steps:[{title:"Key idea",body:"External failures are found by, or affect, the customer: credits, complaints, lost customers."},{title:"Find the intruder",body:"Re-running a billing job **before** bills go out is caught inside the company — **internal** failure."}],final:"Re-running a job before dispatch = internal failure → answer **C**",whyWrong:["Credits for missed appointments are paid after the customer is affected — external.","Complaint handling is caused by defects that reached the customer — external.","","Lost customers (churn) are a classic external failure cost."],bookRef:"Book p. 584"},{id:"sv-1-099",phase:1,topic:"1.2.4",qtype:"calculation",difficulty:1,stem:"A home-broadband help desk sorts **560** complaints for a Pareto chart: Slow speed **196**, Dropped connection **154**, Billing query **98**, Wi-Fi coverage **70**, Other **42**. What percentage does the **second bar** (Dropped connection) represent on its own?",options:["27.5%","37.9%","44.0%","62.5%"],answer:0,hint:"Bar % = category count ÷ grand total × 100.",steps:[{title:"Pick the formula",body:"$$\\%_{i}=\\dfrac{f_{i}}{\\sum f}\\times 100$$"},{title:"Substitute and calculate",body:"$$\\%=\\dfrac{154}{560}\\times 100=27.5\\%$$"},{title:"Interpret",body:"The cumulative line at this bar would read 62.5%, but the bar itself is 27.5%."}],final:"Dropped connection = 27.5% → answer **A**",whyWrong:["","37.9% divides by the other complaints (406) instead of the grand total.","44.0% divides by the top two categories only (350).","62.5% is the cumulative percentage at the second bar, not the bar itself."],bookRef:"Book p. 587"},{id:"sv-1-100",phase:1,topic:"1.2.4",qtype:"calculation",difficulty:3,stem:`Billing errors last quarter, with the average cost to fix each one:

| Error type | Count | Cost per error (OMR) |
|---|---|---|
| Late bill | 150 | 4 |
| Wrong tariff | 120 | 15 |
| Missing discount | 45 | 60 |
| Duplicate charge | 30 | 80 |
| Other | 25 | 10 |

On a **cost-weighted** Pareto chart, which category is the first bar, and what share of total cost does it carry?`,options:["Late bill, 40.5%","Duplicate charge, 31.0%","Missing discount, 12.2%","Missing discount, 34.8%"],answer:3,hint:"Weighted value = count × cost per item; rank by weighted value; share = weighted value ÷ total weighted value × 100.",steps:[{title:"Weight each category",body:"Late 150 × 4 = 600; Wrong tariff 120 × 15 = 1,800; Missing discount 45 × 60 = 2,700; Duplicate 30 × 80 = 2,400; Other 25 × 10 = 250. Total = 7,750."},{title:"Rank",body:"Missing discount (2,700) > Duplicate (2,400) > Wrong tariff (1,800) > Late (600) > Other (250)."},{title:"Calculate the share",body:"$$\\%=\\dfrac{2700}{7750}\\times 100=34.8\\%$$"},{title:"Decide",body:"By cost, **Missing discount** leads with 34.8% — even though Late bill is the most frequent error."}],final:"Missing discount, 34.8% of cost → answer **D**",whyWrong:["Late bill leads by count (150 of 370 = 40.5%) but not by cost.","Duplicate charge has the highest cost per error, but its total (2,400) is second; 2,400 of 7,750 = 31.0%.","Right category, but 12.2% is its share of the count (45 of 370), not of the cost.",""],trap:"A frequency Pareto and a cost Pareto can rank categories very differently.",bookRef:"Book p. 587"},{id:"sv-1-101",phase:1,topic:"1.2.4",qtype:"calculation",difficulty:3,stem:`Porting rejections for one month are listed as recorded:

| Reason | Count |
|---|---|
| Port-in data mismatch | 64 |
| SIM swap pending | 18 |
| Other | 30 |
| KYC rejection | 120 |
| Number not released | 48 |

After building a correct Pareto chart, what is the **cumulative percentage at the fourth bar**?`,options:["6.4%","82.9%","89.3%","93.6%"],answer:2,hint:"Sort categories in descending order, keep “Other” last, then cum% = running total ÷ grand total × 100.",steps:[{title:"Sort",body:"KYC 120 → Port-in 64 → Number not released 48 → SIM swap 18 → **Other 30 last**. Total = 280."},{title:"Pick the formula",body:"$$\\text{Cum}\\%_{k}=\\dfrac{\\sum_{i=1}^{k} f_{i}}{\\sum f}\\times 100$$"},{title:"Calculate",body:"$$\\text{Cum}\\%_{4}=\\dfrac{120+64+48+18}{280}\\times 100=\\dfrac{250}{280}\\times 100=89.3\\%$$"}],final:"Cum% at bar 4 = 89.3% → answer **C**",whyWrong:["6.4% is the fourth bar on its own (18 of 280), not the cumulative value.","82.9% accumulates the first four rows in the order recorded, without sorting.","","93.6% sorts “Other” (30) into fourth place by size; Other always goes last."],bookRef:"Book p. 587"},{id:"sv-1-102",phase:1,topic:"1.2.4",qtype:"output",difficulty:2,stem:`A NOC team charts **400** network faults:

\`\`\`
Pareto Chart of Fault Type

Fault       Fibre cut   Power   Config   Other
Count              96      84       60     160
Percent          24.0    21.0     15.0    40.0
Cum %            24.0    45.0     60.0   100.0
\`\`\`

What should the team do next?`,options:["Start a project on fibre cuts, because it is the tallest named bar","Break “Other” into its underlying fault types and redraw the chart, because it is the largest group","Conclude the 80:20 rule does not apply, so Pareto analysis is useless here","Remove “Other” from the data and recalculate the percentages"],answer:1,hint:"“Other” should be small; if it is the biggest bar, the categories are not specific enough.",steps:[{title:"Locate",body:"“Other” holds 160 faults — 40% — more than any named category."},{title:"Apply",body:"A large “Other” hides the real vital few. Re-code it into specific fault types, then redraw before choosing a focus."},{title:"Eliminate",body:"Picking fibre cuts now may miss a bigger hidden category; 80:20 is a guideline, not a test of usefulness; deleting data distorts the picture."}],final:"Break down “Other” first → answer **B**",whyWrong:["Fibre cuts is only 24%; a category inside “Other” may be larger.","","The 80:20 split is a rule of thumb; the chart is still useful once categories are clear.","Removing 40% of the faults hides real problems and changes the denominator."],bookRef:"Book p. 587"},{id:"sv-1-103",phase:1,topic:"1.2.4",qtype:"concept",difficulty:1,stem:"What does the **Pareto principle (80:20 rule)** state?",options:["Exactly 80% of defects always come from exactly 20% of causes","80% of a project’s budget should go to the first 20% of the schedule","A process is acceptable when 80% of units pass inspection","Most of the effect usually comes from a small number of causes — the vital few"],answer:3,hint:"It is a rule of thumb about concentration, not an exact law.",steps:[{title:"Key idea",body:"The book defines the Pareto principle as the majority of influence coming from a minority of inputs: the **vital few** versus the **trivial many**."},{title:"Eliminate",body:"80:20 is not exact; the real split may be 70:30 or 90:10. It is unrelated to budgets or pass rates."}],final:"Most effects come from a vital few causes → answer **D**",whyWrong:["The split is a guideline, not an exact law — “exactly” and “always” make this false.","This is not a budgeting rule.","An 80% pass rate is not a quality standard and has nothing to do with Pareto.",""],bookRef:"Book p. 587"},{id:"sv-1-104",phase:1,topic:"1.2.4",qtype:"scenario",difficulty:1,stem:"A first Pareto chart shows that **“Order fallout”** accounts for 52% of delayed activations. The category still covers many different failures. What is the BEST next step?",options:["Draw a second-level Pareto chart that breaks “Order fallout” down by fallout reason","Start a fishbone diagram for every category on the first chart","Draw a control chart of total delayed activations","Pick the smallest category, because it will be easiest to fix"],answer:0,hint:"Pareto charts can be layered: drill into the biggest bar to find a specific focus.",steps:[{title:"Key idea",body:"A **second-level (drill-down) Pareto** stratifies the biggest bar to find a specific, actionable vital few."},{title:"Apply",body:"Breaking “Order fallout” down by reason narrows the project focus before any cause analysis starts."}],final:"Drill down with a second-level Pareto → answer **A**",whyWrong:["","Fishbones for every category waste effort on the trivial many.","A control chart shows stability over time, not which fallout reason dominates.","Choosing the smallest bar ignores the Pareto logic of attacking the biggest effect."],bookRef:"Book p. 587"},{id:"sv-1-105",phase:1,topic:"1.2.5",qtype:"calculation",difficulty:1,stem:"An eSIM activation check reviews **3,000** orders. Each order has **5** defect opportunities. The review finds **45** defects. What is the **DPO** (defects per opportunity)?",options:["0.003","0.015","0.075","3,000"],answer:0,hint:"DPO = defects ÷ (units × opportunities per unit).",steps:[{title:"Write what is given",body:"$D = 45$, $U = 3000$, $O = 5$."},{title:"Pick the formula",body:"$$DPO=\\dfrac{D}{U\\times O}$$"},{title:"Substitute and calculate",body:"$$DPO=\\dfrac{45}{3000\\times 5}=\\dfrac{45}{15{,}000}=0.003$$"},{title:"Interpret",body:"0.3% of opportunities are defective; × 10⁶ gives 3,000 DPMO."}],final:"DPO = 0.003 → answer **A**",whyWrong:["","0.015 is DPU (45 ÷ 3,000): the opportunities were left out.","0.075 multiplies by the 5 opportunities instead of dividing by them.","3,000 is DPMO (DPO × 10⁶), not DPO."],bookRef:"Book p. 585"},{id:"sv-1-106",phase:1,topic:"1.2.5",qtype:"calculation",difficulty:3,stem:"An audit covers two contract types: **200** consumer contracts with **4** opportunities each and **300** business contracts with **6** opportunities each. **26** defects are found in total. What is the combined **DPMO**?",options:["5,200","10,000","10,400","52,000"],answer:1,hint:"DPMO = total defects ÷ total opportunities × 10⁶, where total opportunities = Σ(units × opportunities per unit).",steps:[{title:"Count total opportunities",body:"$$TOP=200\\times 4+300\\times 6=800+1800=2600$$"},{title:"Pick the formula",body:"$$DPMO=\\dfrac{D}{TOP}\\times 10^{6}$$"},{title:"Substitute and calculate",body:"$$DPMO=\\dfrac{26}{2600}\\times 10^{6}=0.01\\times 10^{6}=10{,}000$$"},{title:"Interpret",body:"1% of all opportunities were defective."}],final:"DPMO = 10,000 → answer **B**",whyWrong:["5,200 uses 10 opportunities per contract (4 + 6 added) for all 500 contracts.","","10,400 averages the opportunities to 5 per contract (2,500 total); the mix is 200/300, not 50/50.","52,000 ignores opportunities (26 ÷ 500 × 10⁶ = DPU × 10⁶)."],trap:"With mixed products, add up the opportunities for each group — do not average the opportunity counts.",bookRef:"Book pp. 585, 587"},{id:"sv-1-107",phase:1,topic:"1.2.5",qtype:"calculation",difficulty:2,stem:"A legal team reviews **400** enterprise contracts, each with **12** checked fields. It finds **96** defects, spread over **80** contracts. What is the **DPMO**?",options:["0.24","16,667","20,000","240,000"],answer:2,hint:"DPMO counts every defect (not defective units) against units × opportunities.",steps:[{title:"Write what is given",body:"$D = 96$ (defects), $U = 400$, $O = 12$. The 80 defective contracts are not used in DPMO."},{title:"Pick the formula",body:"$$DPMO=\\dfrac{D}{U\\times O}\\times 10^{6}$$"},{title:"Substitute and calculate",body:"$$DPMO=\\dfrac{96}{400\\times 12}\\times 10^{6}=\\dfrac{96}{4800}\\times 10^{6}=20{,}000$$"}],final:"DPMO = 20,000 → answer **C**",whyWrong:["0.24 is DPU (96 ÷ 400).","16,667 uses the 80 defective contracts instead of the 96 defects.","","240,000 ignores the 12 opportunities (DPU × 10⁶)."],bookRef:"Book p. 585"},{id:"sv-1-108",phase:1,topic:"1.2.5",qtype:"calculation",difficulty:1,stem:"A five-step enterprise order process has first time yields of **98%, 96%, 99%, 93% and 97%**. What is the **rolled throughput yield** (to two decimals)?",options:["0.16","0.84","0.93","0.97"],answer:1,hint:"RTY = product of the step first time yields.",steps:[{title:"Pick the formula",body:"$$RTY=FTY_{1}\\times FTY_{2}\\times \\dots \\times FTY_{n}$$"},{title:"Substitute",body:"$$RTY=0.98\\times 0.96\\times 0.99\\times 0.93\\times 0.97$$"},{title:"Calculate",body:"$$RTY=0.840$$"},{title:"Interpret",body:"Only about 84% of orders pass all five steps right first time."}],final:"RTY ≈ 0.84 → answer **B**",whyWrong:["0.16 is the loss (1 − RTY), not the yield.","","0.93 is the lowest single step, not the whole process.","0.97 averages the yields instead of multiplying them."],bookRef:"Book pp. 105, 588"},{id:"sv-1-109",phase:1,topic:"1.2.5",qtype:"calculation",difficulty:3,stem:"A four-step returns process has a rolled throughput yield of **0.81**. What is the **normalized yield** — the average first time yield per step that would give the same RTY?",options:["0.20","0.66","0.90","0.95"],answer:3,hint:"Normalized yield = the n-th root of RTY, where n is the number of steps.",steps:[{title:"Write what is given",body:"$RTY = 0.81$, $n = 4$ steps."},{title:"Pick the formula",body:"$$Y_{norm}=\\sqrt[n]{RTY}$$"},{title:"Substitute and calculate",body:"$$Y_{norm}=\\sqrt[4]{0.81}=0.949\\approx 0.95$$"},{title:"Check",body:"$$0.949\\times 0.949\\times 0.949\\times 0.949=0.81$$"}],final:"Normalized yield ≈ 0.95 → answer **D**",whyWrong:["0.20 divides RTY by the number of steps instead of taking the 4th root.","0.66 squares RTY (0.81 × 0.81) instead of taking a root.","0.90 takes the square root regardless of the number of steps (that would suit two steps).",""],bookRef:"Book p. 588"},{id:"sv-1-110",phase:1,topic:"1.2.5",qtype:"calculation",difficulty:3,stem:"A field-service process has an RTY of **0.86**. Assuming defects follow a Poisson distribution, what is the implied **total DPU**?",options:["0.066","0.140","0.151","1.163"],answer:2,hint:"Under Poisson, RTY ≈ e^(−DPU), so DPU = −ln(RTY).",steps:[{title:"Pick the formula",body:"$$RTY=e^{-DPU}\\quad\\Rightarrow\\quad DPU=-\\ln(RTY)$$"},{title:"Substitute and calculate",body:"$$DPU=-\\ln(0.86)=\\ln\\left(\\dfrac{1}{0.86}\\right)=0.151$$"},{title:"Interpret",body:"About 0.15 defects per unit on average. This is a little higher than 1 − RTY = 0.14, because some units carry more than one defect."}],final:"DPU = −ln(0.86) ≈ 0.151 → answer **C**",whyWrong:["0.066 uses log base 10 instead of the natural log.","0.140 is 1 − RTY, the share of units with at least one defect — it undercounts units with several defects.","","1.163 is 1 ÷ 0.86, which has no meaning here."],bookRef:"Book pp. 225, 588"},{id:"sv-1-111",phase:1,topic:"1.2.5",qtype:"calculation",difficulty:2,stem:"A SIM-dispatch hub runs **two 8-hour shifts**. Each shift has **45 minutes** of planned breaks. Daily customer demand is **600** packages. What is the **takt time** in seconds?",options:["43.5 s","87 s","96 s","174 s"],answer:1,hint:"Takt = net available time ÷ customer demand for the same period.",steps:[{title:"Net available time",body:"$$2\\times(480-45)=870\\text{ min}=870\\times 60=52{,}200\\text{ s}$$"},{title:"Pick the formula",body:"$$\\text{Takt}=\\dfrac{\\text{net available time}}{\\text{demand}}$$"},{title:"Substitute and calculate",body:"$$\\text{Takt}=\\dfrac{52{,}200}{600}=87\\text{ s}$$"},{title:"Interpret",body:"One package must leave the hub every 87 seconds to keep pace with demand."}],final:"Takt = 87 s → answer **B**",whyWrong:["43.5 s uses one shift’s time against the whole day’s demand.","","96 s uses gross time (960 min) and forgets to remove planned breaks.","174 s divides the whole day’s time by one shift’s demand (300)."],bookRef:"Book p. 585"},{id:"sv-1-112",phase:1,topic:"1.2.5",qtype:"calculation",difficulty:2,stem:"A complaints team closes **600** cases per week (5 working days). Management wants the average lead time to be **3 working days**. Using **Little’s Law**, how many cases can be in progress on average?",options:["40","200","360","1,800"],answer:2,hint:"Little’s Law: lead time = WIP ÷ throughput, so WIP = throughput × lead time (same time units).",steps:[{title:"Match the units",body:"$$\\text{Throughput}=\\dfrac{600}{5}=120\\text{ cases per day}$$"},{title:"Pick the formula",body:"$$\\text{Lead time}=\\dfrac{WIP}{\\text{Throughput}}\\quad\\Rightarrow\\quad WIP=\\text{Throughput}\\times\\text{Lead time}$$"},{title:"Substitute and calculate",body:"$$WIP=120\\times 3=360$$"},{title:"Interpret",body:"Keep WIP at about **360** cases; more WIP means longer lead time at the same throughput."}],final:"WIP = 360 cases → answer **C**",whyWrong:["40 divides daily throughput by lead time instead of multiplying.","200 divides weekly throughput by lead time.","","1,800 multiplies a weekly rate by a lead time in days — the units do not match."],bookRef:"Book p. 585"},{id:"sv-1-113",phase:1,topic:"1.2.5",qtype:"calculation",difficulty:3,stem:"A router-refurbishment cell has **420 minutes** of net working time a day and completes **280** units. Customer demand is **300** units a day over the same 420 minutes. What is the cell’s **cycle time**, and can it meet demand?",options:["0.67 min per unit — yes, it is faster than takt","1.40 min per unit — yes, it matches takt","1.71 min per unit — no, it is slower than takt","1.50 min per unit — no, it is slower than the 1.40-min takt"],answer:3,hint:"Cycle time = net working time ÷ units completed; takt = net available time ÷ demand; demand is met only if cycle time ≤ takt.",steps:[{title:"Pick the formulas",body:"$$CT=\\dfrac{\\text{net working time}}{\\text{units completed}}\\qquad \\text{Takt}=\\dfrac{\\text{net available time}}{\\text{demand}}$$"},{title:"Calculate cycle time",body:"$$CT=\\dfrac{420}{280}=1.50\\text{ min per unit}$$"},{title:"Calculate takt",body:"$$\\text{Takt}=\\dfrac{420}{300}=1.40\\text{ min per unit}$$"},{title:"Decide",body:"1.50 > 1.40, so the cell is too slow: it makes 280, not 300, a day."}],final:"CT = 1.50 min > takt 1.40 min → cannot meet demand → answer **D**",whyWrong:["0.67 is units per minute (280 ÷ 420), the inverse of cycle time.","1.40 is the takt time, not the cell’s cycle time.","1.71 uses a gross 480-minute day instead of the 420 minutes of net working time.",""],bookRef:"Book p. 585"},{id:"sv-1-114",phase:1,topic:"1.2.5",qtype:"calculation",difficulty:2,stem:"A three-step order process has DPUs of **0.05, 0.12 and 0.03**. Assuming Poisson-distributed defects, what is the approximate **RTY**?",options:["0.20","0.80","0.82","0.93"],answer:2,hint:"Total DPU = sum of step DPUs; RTY ≈ e^(−total DPU).",steps:[{title:"Add the DPUs",body:"$$DPU_{total}=0.05+0.12+0.03=0.20$$"},{title:"Pick the formula",body:"$$RTY\\approx e^{-DPU_{total}}$$"},{title:"Substitute and calculate",body:"$$RTY\\approx e^{-0.20}=0.819\\approx 0.82$$ Same result step by step: $$e^{-0.05}\\times e^{-0.12}\\times e^{-0.03}=0.9512\\times 0.8869\\times 0.9704=0.819$$"}],final:"RTY ≈ 0.82 → answer **C**",whyWrong:["0.20 is the total DPU, not a yield.","0.80 uses 1 − DPU, a straight-line shortcut that understates the Poisson yield.","","0.93 averages the step yields (1 − DPU each) instead of combining them across steps."],bookRef:"Book pp. 225, 588"},{id:"sv-1-115",phase:1,topic:"1.2.5",qtype:"output",difficulty:2,stem:`Inspectors count defects on each of **500** installation reports:

\`\`\`
Tally for Discrete Variables: Defects per report

Defects  Count  CumCnt  Percent
0          410     410    82.00
1           60     470    12.00
2           20     490     4.00
3           10     500     2.00
     N=    500
\`\`\`

What is the **DPU**?`,options:["0.18","0.26","0.82","1.44"],answer:1,hint:"DPU = total defects ÷ total units; total defects = Σ(defects per unit × count).",steps:[{title:"Total the defects",body:"$$D=0\\times 410+1\\times 60+2\\times 20+3\\times 10=0+60+40+30=130$$"},{title:"Pick the formula",body:"$$DPU=\\dfrac{D}{U}$$"},{title:"Substitute and calculate",body:"$$DPU=\\dfrac{130}{500}=0.26$$"},{title:"Interpret",body:"FTY is 410 ÷ 500 = 0.82, but defects per unit (0.26) is higher than the defective share (0.18) because some reports carry 2–3 defects."}],final:"DPU = 0.26 → answer **B**",whyWrong:["0.18 is the proportion of defective reports (90 ÷ 500), not defects per unit.","","0.82 is the first time yield (reports with zero defects).","1.44 divides the defects by the 90 defective reports instead of all 500 reports."],bookRef:"Book p. 585"},{id:"sv-1-116",phase:1,topic:"1.2.5",qtype:"output",difficulty:3,stem:`A one-person quotation desk has **450 minutes** of net time a day; customers request **80** quotes a day. Cycle times for 60 quotes:

\`\`\`
Descriptive Statistics: Quote cycle time (min)

Variable    N   Mean  StDev  Median  Minimum  Maximum
CycleTime  60   6.20   1.90    5.40     3.10    12.80
\`\`\`

Which conclusion is correct?`,options:["The median (5.40) is below takt, so the desk meets demand","Takt is 6.00 minutes (480 ÷ 80), so the desk is only slightly slow","Takt is 5.63 minutes; the mean cycle time of 6.20 is above it, so demand cannot be met without change","Takt cannot be found without the standard deviation"],answer:2,hint:"Takt = net available time ÷ demand; capacity depends on the mean cycle time because all quotes must be done.",steps:[{title:"Calculate takt",body:"$$\\text{Takt}=\\dfrac{450}{80}=5.63\\text{ min per quote}$$"},{title:"Locate",body:"Mean cycle time = **6.20** min. Total work time is driven by the mean, not the median."},{title:"Decide",body:"6.20 > 5.63: at 6.20 min per quote the desk finishes about 450 ÷ 6.2 ≈ 73 quotes, short of 80."}],final:"Mean CT 6.20 > takt 5.63 → cannot meet demand → answer **C**",whyWrong:["Capacity depends on the total time used, i.e. the mean; with right-skewed times the median understates the load.","480 is a gross day; takt uses the 450 minutes of net available time.","","Takt needs only available time and demand; the SD does not enter the formula."],bookRef:"Book p. 585"},{id:"sv-1-117",phase:1,topic:"1.2.5",qtype:"table",difficulty:3,stem:`A four-step activation process recorded one month of results:

| Step | Units in | Right first time |
|---|---|---|
| Order capture | 1,200 | 1,140 |
| Credit check | 1,180 | 1,050 |
| Provisioning | 1,160 | 1,090 |
| Activation | 1,150 | 1,120 |

What is the **rolled throughput yield**?`,options:["0.77","0.89","0.93","0.94"],answer:0,hint:"FTY per step = right first time ÷ units in that step; RTY = product of the FTYs.",steps:[{title:"Step FTYs",body:"$$FTY_{1}=\\dfrac{1140}{1200}=0.950\\quad FTY_{2}=\\dfrac{1050}{1180}=0.890$$ $$FTY_{3}=\\dfrac{1090}{1160}=0.940\\quad FTY_{4}=\\dfrac{1120}{1150}=0.974$$"},{title:"Pick the formula",body:"$$RTY=FTY_{1}\\times FTY_{2}\\times FTY_{3}\\times FTY_{4}$$"},{title:"Calculate",body:"$$RTY=0.950\\times 0.890\\times 0.940\\times 0.974=0.774$$"},{title:"Interpret",body:"Only about 77% of orders pass every step first time; credit check (0.89) is the biggest hidden factory."}],final:"RTY ≈ 0.77 → answer **A**",whyWrong:["","0.89 is the lowest step (credit check) on its own, not the whole process.","0.93 divides the last step’s right-first-time count (1,120) by the 1,200 that entered step 1 — it ignores earlier rework.","0.94 averages the four FTYs instead of multiplying them."],bookRef:"Book pp. 105, 588"},{id:"sv-1-118",phase:1,topic:"1.3.1",qtype:"calculation",difficulty:2,stem:"For a business case, a Green Belt sizes the cost of repeat installation visits. The operator completes **3,500** fibre installations **per month**; **9%** need a repeat visit; each repeat visit costs **OMR 32**. What is the **annual** cost of the problem?",options:["OMR 10,080","OMR 120,960","OMR 1,223,040","OMR 1,344,000"],answer:1,hint:"Annual cost = monthly volume × 12 × defect rate × cost per defect.",steps:[{title:"Write what is given",body:"3,500 installs per month; repeat rate 0.09; OMR 32 per repeat."},{title:"Annualise the volume",body:"$$3{,}500\\times 12=42{,}000\\text{ installs}$$"},{title:"Calculate",body:"$$\\text{Cost}=42{,}000\\times 0.09\\times 32=3{,}780\\times 32=120{,}960$$"},{title:"Interpret",body:"About **OMR 121k** a year is at stake — the “size of the prize” for the business case."}],final:"Annual cost = OMR 120,960 → answer **B**",whyWrong:["10,080 is one month’s cost — it was not annualised.","","1,223,040 prices the 91% of installs that did not need a repeat visit.","1,344,000 prices every installation, not just the 9% repeats."],bookRef:"Book p. 230"},{id:"sv-1-119",phase:1,topic:"1.3.1",qtype:"output",difficulty:2,stem:`To scope a rework-reduction project, a Green Belt totals last year’s rework cost by product line:

\`\`\`
Tabulated Statistics: Product line; Sum of Rework cost (OMR)

Product line      Count      Sum
Fibre home         1240   186,000
Enterprise          310   148,800
Mobile postpaid    2900    87,000
Prepaid            4100    41,000
All                8550   462,800
\`\`\`

Which scope gives the project the BEST start?`,options:["All four product lines, so that no rework is missed","Prepaid, because it has the most rework cases","Enterprise, because each case costs the most (about OMR 480)","Fibre home, because it carries the largest share of rework cost (about 40%)"],answer:3,hint:"Scope where the business impact (cost) is concentrated, and keep the project manageable.",steps:[{title:"Locate",body:"Fibre home = 186,000 of 462,800. $$\\%=\\dfrac{186{,}000}{462{,}800}\\times 100=40.2\\%$$"},{title:"Apply",body:"A good scope is narrow enough to finish in a few months and targets the biggest impact. Fibre home is the largest single block of cost."},{title:"Eliminate",body:"All lines is too broad; Prepaid is many cheap cases (8.9% of cost); Enterprise is costly per case but smaller in total (32.2%)."}],final:"Scope to Fibre home (≈ 40% of rework cost) → answer **D**",whyWrong:["Scoping all lines at once is “boiling the ocean” and makes the project hard to finish.","Prepaid has the most cases but only OMR 41,000 (8.9%) of cost.","Cost per case is high, but the total (OMR 148,800) is below Fibre home.",""],bookRef:"Book p. 230"},{id:"sv-1-120",phase:1,topic:"1.3.1",qtype:"not-except",difficulty:2,stem:"A good **problem statement** in a project charter has all of the following characteristics EXCEPT:",options:["It names the likely root cause and the solution to apply","It states what is wrong and where it occurs","It quantifies the gap with data and a time frame","It describes the impact on customers or the business"],answer:0,hint:"A problem statement bounds and describes the problem — it does not assume causes or answers.",steps:[{title:"Key idea",body:"The book defines the problem statement as one that **bounds and describes** the business problem: what, where, when, how big, and its impact."},{title:"Find the intruder",body:"Naming a root cause or solution pre-judges Analyze and Improve — it is not part of a good problem statement."}],final:"No causes or solutions in a problem statement → answer **A**",whyWrong:["","What and where are core parts of a problem statement.","Quantifying the gap with data and time is essential.","Stating the impact explains why the problem matters."],bookRef:"Book p. 587"},{id:"sv-1-121",phase:1,topic:"1.3.1",qtype:"scenario",difficulty:1,stem:"Baseline: **74%** of P2 incidents are restored within SLA (Jan–Jun). Which is the BEST **goal statement** for the charter?",options:["Improve P2 restoration as much as possible","Implement automated ticket routing to raise SLA compliance","Make the vendor solve P2 incidents faster from now on","Increase P2 incidents restored within SLA from 74% to 90% by 31 December"],answer:3,hint:"A goal statement is specific, measurable, has a baseline, a target and a date, and does not name a solution.",steps:[{title:"Key idea",body:"A good goal follows SMART: the metric, baseline (74%), target (90%) and deadline (31 Dec)."},{title:"Eliminate",body:"“As much as possible” is not measurable; automated routing is a solution; “faster from now on” has no target or date and blames a party."}],final:"Metric, baseline, target and date → answer **D**",whyWrong:["No target or deadline — it cannot be judged as achieved.","It names a solution; the goal should state the result, not the method.","It has no measure, target or date, and it targets people rather than the process.",""],bookRef:"Book p. 587"},{id:"sv-1-122",phase:1,topic:"1.3.1",qtype:"scenario",difficulty:3,stem:"Halfway through Measure, the Champion asks the team to also “fix the enterprise billing process” alongside the agreed consumer-billing scope. The new request would double the data collection. What should the Green Belt do?",options:["Raise it as a scope change at a review with the Champion, and agree to keep the current scope or formally revise the charter (goal, timeline, resources)","Quietly add enterprise billing to the data collection to keep the Champion happy","Refuse, because a charter can never be changed once signed","Drop the consumer scope and restart with enterprise billing only"],answer:0,hint:"Scope creep is managed through the charter, with the Champion, not around it.",steps:[{title:"Key idea",body:"The in-scope/out-of-scope section protects the project from **scope creep**. The charter is a living document, but changes must be agreed openly."},{title:"Apply",body:"The Green Belt should show the impact (double the data, later finish) and let the Champion decide: keep scope, start a separate project, or revise the charter with new resources and dates."}],final:"Manage the change formally through the charter → answer **A**",whyWrong:["","Silently widening the scope is classic scope creep — the project will overrun.","Charters can be revised at reviews; “never” is wrong.","Abandoning the agreed scope wastes the work done and was not what the Champion asked."],bookRef:"Book p. 231"},{id:"sv-1-123",phase:1,topic:"1.3.1",qtype:"concept",difficulty:1,stem:"What is the main purpose of the **business case** section of a project charter?",options:["To list the team members and their roles","To record the root causes the team expects to find","To give the project timeline by phase","To explain why the project matters now — its link to business goals and the expected financial or customer impact"],answer:3,hint:"Business case = why this project, why now.",steps:[{title:"Key idea",body:"The business case justifies the project: link to strategy, cost of the problem (e.g. COPQ) and the benefit of fixing it."},{title:"Eliminate",body:"Team, timeline and scope are other charter sections; root causes are not known yet."}],final:"Business case = why it matters now → answer **D**",whyWrong:["Team members belong to the team/roles section.","Root causes are found in Analyze; the charter must not assume them.","The timeline is the project plan/milestones section.",""],bookRef:"Book p. 578"},{id:"sv-1-124",phase:1,topic:"1.3.1",qtype:"concept",difficulty:2,stem:"Which statement about the project charter is MOST accurate?",options:["It is a living document that is reviewed at tollgates and updated if data change the problem or scope","It is fixed once signed and must never be changed","It is written in Control to record what the project achieved","It is needed only for Black Belt projects, not Green Belt projects"],answer:0,hint:"The book’s Measure checklist asks: “Has the problem statement changed?”",steps:[{title:"Key idea",body:"The charter is drafted in Define and **revisited** — the book’s Measure checklist asks whether the problem statement has changed."},{title:"Apply",body:"Measure data often sharpen the problem or scope; the charter is updated and re-agreed with the Champion."}],final:"The charter is a living document → answer **A**",whyWrong:["","Charters are revised when new data change the picture; they are not frozen.","The charter starts the project in Define; Control verifies results against it.","Every Belt project, Green Belt included, needs a charter."],bookRef:"Book p. 231"},{id:"sv-1-125",phase:1,topic:"1.3.1",qtype:"scenario",difficulty:2,stem:"A draft charter says: *“Because agents are poorly trained, 22% of billing disputes are reopened.”* What is the main weakness?",options:["It gives a percentage instead of a count","It does not name the Champion","It assumes a root cause (poor training) before any data have been analysed","It is too short to be a problem statement"],answer:2,hint:"A problem statement describes the symptom with data; it does not assume why.",steps:[{title:"Key idea",body:"A problem statement describes **what, where, when and how big** — not why. Causes are proven in Analyze."},{title:"Apply",body:"“Because agents are poorly trained” jumps to a cause and may send the team after the wrong X. A better draft: “22% of billing disputes closed Jan–Jun were reopened within 30 days, costing …”."}],final:"It assumes a root cause → answer **C**",whyWrong:["A percentage is a valid way to quantify the gap.","The Champion is named elsewhere in the charter, not inside the problem statement.","","Length is not the issue; the built-in cause is."],bookRef:"Book p. 587"},{id:"sv-1-126",phase:1,topic:"1.3.1",qtype:"sequence",difficulty:2,stem:`Put these project-start activities in the usual order:

- **P** Champion approves the charter at the Define tollgate
- **Q** Leadership screens and prioritises candidate projects
- **R** Green Belt drafts the charter with the Champion
- **S** Champion selects a project and assigns a Belt

Which order is correct?`,options:["R → Q → S → P","Q → R → S → P","S → Q → R → P","Q → S → R → P"],answer:3,hint:"Choose the project, then the person, then write the charter, then approve it.",steps:[{title:"Key idea",body:"Projects are **screened and prioritised** first; the Champion then **selects** one and assigns a Belt; the Belt and Champion **draft** the charter; the Champion **approves** it at the tollgate."},{title:"Apply",body:"That is Q → S → R → P."}],final:"Screen → select and assign → draft → approve → answer **D**",whyWrong:["A charter cannot be drafted before a project has been chosen and a Belt assigned.","The Belt drafts the charter after being assigned (S before R).","Selection follows screening of candidate projects, so Q comes before S.",""],bookRef:"Book p. 584"},{id:"sv-1-127",phase:1,topic:"1.3.2",qtype:"calculation",difficulty:1,stem:"A project cuts the mean time to restore enterprise links from **240 minutes** to **168 minutes**. What is the **percentage improvement**?",options:["30.0%","42.9%","70.0%","72.0%"],answer:0,hint:"% improvement = (baseline − new) ÷ baseline × 100.",steps:[{title:"Pick the formula",body:"$$\\%\\text{ improvement}=\\dfrac{\\text{Baseline}-\\text{New}}{\\text{Baseline}}\\times 100$$"},{title:"Substitute and calculate",body:"$$\\%=\\dfrac{240-168}{240}\\times 100=\\dfrac{72}{240}\\times 100=30.0\\%$$"}],final:"30.0% improvement → answer **A**",whyWrong:["","42.9% divides the gain by the new value (168) instead of the baseline.","70.0% is new ÷ baseline — the share remaining, not the improvement.","72.0% reports the 72-minute reduction as if it were a percentage."],bookRef:"Book p. 584"},{id:"sv-1-128",phase:1,topic:"1.3.2",qtype:"output",difficulty:3,stem:`The charter goal is to **reduce the mean days to resolve** complaints **by at least 30%**. Pilot results:

\`\`\`
Descriptive Statistics: Days to resolve

Period      N   Mean  StDev  Median
Baseline  180  14.20   6.10   12.50
Pilot      60   9.80   4.40    8.75
\`\`\`

Is the goal met?`,options:["No — the pilot mean is 69% of baseline, so only 69% of the goal was reached","No — the standard deviation fell by only about 28%","Cannot tell — goals must always be set on the median","Yes — the mean fell by about 31%, which meets the 30% goal"],answer:3,hint:"% reduction = (baseline − new) ÷ baseline × 100, using the metric named in the goal.",steps:[{title:"Locate",body:"The goal names the **mean**: baseline 14.20, pilot 9.80."},{title:"Calculate",body:"$$\\%=\\dfrac{14.20-9.80}{14.20}\\times 100=\\dfrac{4.40}{14.20}\\times 100=31.0\\%$$"},{title:"Decide",body:"31.0% ≥ 30%, so the goal is **met** (to be confirmed with a hypothesis test and sustained in Control)."}],final:"Mean reduced ≈ 31% ≥ 30% → answer **D**",whyWrong:["69% is the share of the baseline that remains (9.80 ÷ 14.20), not the reduction.","The goal is on the mean, not on the standard deviation.","The charter named the mean; the team measures what the goal states.",""],bookRef:"Book p. 574"},{id:"sv-1-129",phase:1,topic:"1.3.2",qtype:"table",difficulty:2,stem:`A project aims to cut **field repair time (MTTR)**. Candidate metrics:

| Metric | What it tracks |
|---|---|
| Repeat fault within 30 days | Whether faster repairs are still good repairs |
| Number of technicians trained | Effort spent on training |
| Average travel distance | One possible cause of long repairs |
| MTTR (hours) | The project’s main target |

Which is the BEST **secondary (consequential) metric**?`,options:["Repeat fault within 30 days","Number of technicians trained","Average travel distance","MTTR (hours)"],answer:0,hint:"A secondary metric guards against harm caused by improving the primary metric.",steps:[{title:"Key idea",body:"The **primary metric** measures the goal; a **secondary metric** checks that improving it does not damage something else."},{title:"Apply",body:"Rushed repairs could raise repeat faults, so “repeat fault within 30 days” is the right guard. MTTR is the primary metric; training count is an activity measure; travel distance is a candidate X."}],final:"Repeat-fault rate guards repair quality → answer **A**",whyWrong:["","Counting trained technicians measures effort, not a consequence of the change.","Travel distance is a possible cause (an X), not a consequential metric.","MTTR is the primary metric itself."],bookRef:"Book pp. 231, 574"},{id:"sv-1-130",phase:1,topic:"1.3.2",qtype:"scenario",difficulty:1,stem:"A Green Belt writes: *“Improve customer onboarding significantly.”* Her Champion asks for a **SMART** goal. Which revision is SMART?",options:["Make onboarding world-class by benchmarking leading operators","Improve onboarding significantly with a new CRM workflow","Cut median onboarding time for SME customers from 9 to 5 working days by 30 June","Reduce onboarding time as far as the team can"],answer:2,hint:"SMART = Specific, Measurable, Achievable, Relevant, Time-bound.",steps:[{title:"Key idea",body:"A SMART goal names a specific metric and population, a measured baseline and target, and a deadline."},{title:"Apply",body:"Only option C has all of these: median onboarding time, SME customers, 9 → 5 days, by 30 June."}],final:"Specific metric, baseline, target and date → answer **C**",whyWrong:["“World-class” is not measurable and has no date.","It names a solution and still has no measure or date.","","“As far as we can” has no target or deadline."],bookRef:"Book p. 231"},{id:"sv-1-131",phase:1,topic:"1.3.2",qtype:"concept",difficulty:2,stem:"In project metrics, what does **entitlement** mean?",options:["The target the Champion demands","The best performance the process has already demonstrated","The average performance over the last year","The performance level written in the customer contract"],answer:1,hint:"Look for “best demonstrated”.",steps:[{title:"Key idea",body:"The book glossary defines entitlement as **best demonstrated performance** — what the process has shown it can do, e.g. its best month."},{title:"Apply",body:"Entitlement helps set realistic goals: closing part of the baseline-to-entitlement gap is believable because the process has done it before."}],final:"Entitlement = best demonstrated performance → answer **B**",whyWrong:["A demanded target may be above or below what the process has shown.","","The long-term average is the baseline, not entitlement.","A contract level is a customer specification (VOC), not demonstrated performance."],bookRef:"Book p. 585"},{id:"sv-1-132",phase:1,topic:"1.3.2",qtype:"concept",difficulty:3,stem:"Which data should a Green Belt use to set the **baseline** of the primary metric?",options:["The best week of the last year, to show what is possible","The most recent two days, because they are the most current","A few hand-picked examples supplied by the process owner","Long-term data that cover the normal range of conditions, so the baseline reflects average performance"],answer:3,hint:"The book: the baseline is average long-term performance with the inputs free to vary.",steps:[{title:"Key idea",body:"The book describes the process baseline as **average long-term performance** when inputs are allowed to vary as normal — so report it with long-term data."},{title:"Eliminate",body:"A best week is entitlement; two days or hand-picked cases are too short or biased to show typical performance."}],final:"Long-term, representative data → answer **D**",whyWrong:["The best period is entitlement, not the baseline.","Two days miss normal variation (shifts, weekdays, month-end).","Hand-picked cases are biased and not representative.",""],bookRef:"Book p. 212"},{id:"sv-1-133",phase:1,topic:"1.3.3",qtype:"calculation",difficulty:2,stem:"A project will deliver hard savings of **OMR 90,000 per year** for **3 years**. It costs **OMR 60,000** one-off plus **OMR 10,000 per year** to run. What is the **benefit-to-cost ratio** over the 3 years?",options:["1.5","2.0","3.0","4.5"],answer:2,hint:"B/C = total benefits ÷ total costs over the same period.",steps:[{title:"Total benefits",body:"$$B=90{,}000\\times 3=270{,}000$$"},{title:"Total costs",body:"$$C=60{,}000+10{,}000\\times 3=90{,}000$$"},{title:"Calculate",body:"$$\\dfrac{B}{C}=\\dfrac{270{,}000}{90{,}000}=3.0$$"},{title:"Decide",body:"Every OMR spent returns OMR 3 — a ratio above 1 supports the business case."}],final:"B/C = 3.0 → answer **C**",whyWrong:["1.5 compares one year’s benefit with the one-off cost only (90,000 ÷ 60,000).","2.0 divides net benefit (270,000 − 90,000) by cost — that is ROI as a ratio, not B/C.","","4.5 ignores the 3 years of running costs (270,000 ÷ 60,000)."],bookRef:"Book pp. 231, 578"},{id:"sv-1-134",phase:1,topic:"1.3.3",qtype:"calculation",difficulty:3,stem:"An operator issues **2,000,000** bills a year, each with **5** defect opportunities. A project cuts billing errors from **1,200 DPMO** to **400 DPMO**. Each error costs **OMR 8** to fix. What is the **annual saving**?",options:["OMR 12,800","OMR 32,000","OMR 64,000","OMR 96,000"],answer:2,hint:"Defects avoided = total opportunities × (old DPMO − new DPMO) ÷ 10⁶; saving = defects avoided × cost per defect.",steps:[{title:"Total opportunities",body:"$$TOP=2{,}000{,}000\\times 5=10{,}000{,}000$$"},{title:"Defects avoided",body:"$$\\Delta D=\\dfrac{TOP\\times(1200-400)}{10^{6}}=\\dfrac{10{,}000{,}000\\times 800}{1{,}000{,}000}=8{,}000$$"},{title:"Calculate the saving",body:"$$\\text{Saving}=8{,}000\\times 8=64{,}000$$"}],final:"Annual saving = OMR 64,000 → answer **C**",whyWrong:["12,800 applies the DPMO change to bills instead of opportunities (1,600 defects).","32,000 prices the defects still left at 400 DPMO, not the defects removed.","","96,000 prices all the defects at the old 1,200 DPMO, as if every defect were removed."],bookRef:"Book p. 231"},{id:"sv-1-135",phase:1,topic:"1.3.3",qtype:"calculation",difficulty:3,stem:"A workflow fix costs **OMR 25,000** one-off and a licence of **OMR 1,200 per month** from month 1. Savings of **OMR 7,500 per month** start only in **month 4**, after implementation. What is the **net benefit in the first 12 months**?",options:["OMR 28,100","OMR 31,700","OMR 42,500","OMR 50,600"],answer:0,hint:"Net benefit = savings for the months they actually occur − one-off cost − running costs for all months paid.",steps:[{title:"Savings",body:"Months 4–12 = 9 months. $$7{,}500\\times 9=67{,}500$$"},{title:"Costs",body:"$$25{,}000+1{,}200\\times 12=25{,}000+14{,}400=39{,}400$$"},{title:"Calculate",body:"$$\\text{Net}=67{,}500-39{,}400=28{,}100$$"}],final:"First-year net benefit = OMR 28,100 → answer **A**",whyWrong:["","31,700 charges the licence for only 9 months; it is paid from month 1.","42,500 leaves out the licence cost completely.","50,600 counts savings for all 12 months, ignoring the 3-month implementation."],bookRef:"Book p. 231"},{id:"sv-1-136",phase:1,topic:"1.3.3",qtype:"calculation",difficulty:3,stem:"Over **2 years** a project delivers hard savings of **OMR 40,000 per year**. It costs **OMR 32,000** one-off and **OMR 4,000 per year** to run. What is the **two-year ROI**?",options:["25%","100%","150%","200%"],answer:1,hint:"ROI = (total benefit − total cost) ÷ total cost × 100, over the same period.",steps:[{title:"Totals",body:"Benefit = 40,000 × 2 = 80,000. Cost = 32,000 + 4,000 × 2 = 40,000."},{title:"Pick the formula",body:"$$ROI=\\dfrac{\\text{Benefit}-\\text{Cost}}{\\text{Cost}}\\times 100$$"},{title:"Calculate",body:"$$ROI=\\dfrac{80{,}000-40{,}000}{40{,}000}\\times 100=100\\%$$"}],final:"ROI = 100% → answer **B**",whyWrong:["25% uses one year’s saving against the one-off cost only: (40,000 − 32,000) ÷ 32,000.","","150% ignores the running costs: (80,000 − 32,000) ÷ 32,000.","200% is benefit ÷ cost (a B/C ratio of 2.0) shown as a percentage, not ROI."],bookRef:"Book p. 231"},{id:"sv-1-137",phase:1,topic:"1.3.3",qtype:"output",difficulty:2,stem:`The charter claimed savings of **OMR 6,000 per month**. Finance verified six months of actual savings after go-live:

\`\`\`
Descriptive Statistics: Verified saving (OMR per month)

Variable  N   Mean  StDev  Minimum  Maximum
Saving    6  4,200    650    3,300    5,100
\`\`\`

What **annual** benefit should the project report?`,options:["OMR 25,200","OMR 50,400","OMR 61,200","OMR 72,000"],answer:1,hint:"Report verified results: annual benefit = verified mean monthly saving × 12.",steps:[{title:"Locate",body:"Verified mean = OMR 4,200 per month."},{title:"Calculate",body:"$$\\text{Annual}=4{,}200\\times 12=50{,}400$$"},{title:"Interpret",body:"Realised vs claimed: $$\\dfrac{4{,}200}{6{,}000}\\times 100=70\\%$$ The report should use the verified OMR 50,400, not the claim."}],final:"Verified annual benefit = OMR 50,400 → answer **B**",whyWrong:["25,200 is only the six months verified so far, not an annual figure.","","61,200 annualises the best month (maximum 5,100), which overstates the benefit.","72,000 annualises the charter claim, not the verified savings."],bookRef:"Book pp. 577–578"},{id:"sv-1-138",phase:1,topic:"1.3.3",qtype:"table",difficulty:3,stem:`A Green Belt classifies claimed benefits (OMR per year):

| Benefit | OMR |
|---|---|
| Planned new hire not needed (not yet in the budget) | 40,000 |
| Future licence upgrade no longer required | 15,000 |
| Overtime budget line reduced | 22,000 |
| Agent hours freed and redeployed to sales | 18,000 |
| Courier contract cancelled | 6,000 |

What is the total **cost avoidance**?`,options:["OMR 55,000","OMR 73,000","OMR 83,000","OMR 101,000"],answer:0,hint:"Hard savings cut current spend; cost avoidance prevents future spend not yet in the budget; soft savings free capacity without cutting spend.",steps:[{title:"Classify",body:"Cost avoidance: planned hire 40,000; licence upgrade 15,000. Hard savings: overtime 22,000; courier 6,000. Soft savings: redeployed hours 18,000."},{title:"Calculate",body:"$$CA=40{,}000+15{,}000=55{,}000$$"}],final:"Cost avoidance = OMR 55,000 → answer **A**",whyWrong:["","73,000 adds the redeployed agent hours, which are soft savings.","83,000 adds the hard savings (overtime and courier), which reduce today’s spend.","101,000 is every claimed benefit added together."],bookRef:"Book p. 585"},{id:"sv-1-139",phase:1,topic:"1.4.1",qtype:"calculation",difficulty:3,stem:"A change-request queue holds **300** requests on average and completes **60** per working day (8 working hours per day). Each request receives **2 hours** of value-added work. What is the **process cycle efficiency (PCE)**?",options:["1.7%","5.0%","25.0%","40.0%"],answer:1,hint:"Lead time = WIP ÷ throughput (Little’s Law); PCE = value-added time ÷ lead time, in the same units.",steps:[{title:"Lead time by Little’s Law",body:"$$LT=\\dfrac{WIP}{TH}=\\dfrac{300}{60}=5\\text{ working days}=5\\times 8=40\\text{ h}$$"},{title:"Pick the formula",body:"$$PCE=\\dfrac{\\text{VA time}}{\\text{lead time}}\\times 100$$"},{title:"Substitute and calculate",body:"$$PCE=\\dfrac{2}{40}\\times 100=5.0\\%$$"},{title:"Interpret",body:"95% of the lead time is waiting or other non-value-added time — the Lean opportunity."}],final:"PCE = 5.0% → answer **B**",whyWrong:["1.7% converts 5 days using 24-hour days (120 h); the throughput is per 8-hour working day.","","25.0% compares the 2 VA hours with one working day (8 h), not the 5-day lead time.","40.0% divides 2 hours by 5 days without converting to the same units."],trap:"Little’s Law and PCE both need consistent time units.",bookRef:"Book p. 117"},{id:"sv-1-140",phase:1,topic:"1.4.1",qtype:"output",difficulty:2,stem:`A team walks **50** enterprise orders through the value stream and splits the lead time:

\`\`\`
Descriptive Statistics: Hours per order by Component

Component          N   Mean
ValueAdded        50   1.80
Waiting/queue     50  30.60
Rework loops      50   3.00
Handoffs          50   0.60
Total lead time   50  36.00
\`\`\`

Which improvement focus will cut lead time the MOST?`,options:["Speed up the value-added work by 50%","Automate the handoffs between teams","Add a final inspection step to catch errors","Reduce queues and waiting between steps, e.g. by limiting WIP and creating flow"],answer:3,hint:"Compare each component with the total; Lean attacks the biggest non-value-added block.",steps:[{title:"Locate",body:"Waiting/queue = 30.6 of 36.0 h. $$\\dfrac{30.6}{36.0}\\times 100=85\\%$$ Value-added is only $$\\dfrac{1.8}{36.0}\\times 100=5\\%$$"},{title:"Apply",body:"Halving the VA work saves 0.9 h; removing all handoff time saves 0.6 h. Waiting is where the time is, so **flow and WIP limits** give the biggest cut."},{title:"Eliminate",body:"An extra inspection adds time and is itself non-value-added."}],final:"Waiting is 85% of lead time → attack queues → answer **D**",whyWrong:["Halving VA time saves only 0.9 of 36 hours.","Handoffs take only 0.6 hours per order.","Inspection adds appraisal time and cost; it does not cut waiting.",""],bookRef:"Book pp. 117, 502"},{id:"sv-1-141",phase:1,topic:"1.4.1",qtype:"not-except",difficulty:1,stem:"The widely used **five Lean principles** include all of the following EXCEPT:",options:["Maximise resource utilisation by building large batches","Specify value from the customer’s point of view","Make the work flow without interruption","Let the customer pull work rather than pushing it"],answer:0,hint:"Value → value stream → flow → pull → perfection.",steps:[{title:"Key idea",body:"The five Lean principles are: specify **value**, map the **value stream**, create **flow**, establish **pull**, pursue **perfection**."},{title:"Find the intruder",body:"Large batches to keep resources busy create inventory and waiting — the opposite of flow and pull."}],final:"Big batches for utilisation is not a Lean principle → answer **A**",whyWrong:["","Specifying value through the customer’s eyes is the first Lean principle.","Flow is the third Lean principle.","Pull is the fourth Lean principle."],bookRef:"Book p. 117"},{id:"sv-1-142",phase:1,topic:"1.4.2",qtype:"concept",difficulty:1,stem:"Which early contribution to Lean thinking is credited to **Henry Ford**?",options:["The Toyota Production System","Single-minute exchange of dies (SMED)","The PDCA cycle","The moving assembly line and continuous flow production"],answer:3,hint:"Ford: Model T, Highland Park, around 1913.",steps:[{title:"Key idea",body:"Ford’s moving assembly line (about 1913) showed the power of **continuous flow** — a foundation that Toyota later adapted for high variety."},{title:"Eliminate",body:"TPS is Ohno/Toyota; SMED is Shingo; PDCA is Shewhart/Deming."}],final:"Ford → moving assembly line and flow → answer **D**",whyWrong:["The Toyota Production System was developed by Taiichi Ohno and the Toyoda family.","SMED was developed by Shigeo Shingo.","PDCA comes from Shewhart and was popularised by Deming.",""],bookRef:"Syllabus 1.4.2"},{id:"sv-1-143",phase:1,topic:"1.4.2",qtype:"concept",difficulty:2,stem:"**Shigeo Shingo**, who worked closely with Toyota, is best known for which two Lean methods?",options:["SMED (quick changeover) and poka-yoke (mistake-proofing)","Control charts and PDCA","Value stream mapping and the five Lean principles","DMAIC and the belt structure"],answer:0,hint:"Think changeovers and error-proofing.",steps:[{title:"Key idea",body:"Shingo developed **SMED** (cutting changeover time to single-digit minutes) and championed **poka-yoke** (designing out human error)."},{title:"Eliminate",body:"Control charts and PDCA are Shewhart/Deming; the five principles were set out later by Womack and Jones; DMAIC and belts come from Motorola/GE."}],final:"Shingo → SMED and poka-yoke → answer **A**",whyWrong:["","Control charts and PDCA belong to Shewhart and Deming.","Value stream mapping and the five principles were popularised by Womack and Jones in the 1990s.","DMAIC and belts are Six Sigma, from Motorola and GE."],bookRef:"Syllabus 1.4.2"},{id:"sv-1-144",phase:1,topic:"1.4.3",qtype:"true-false",difficulty:1,stem:"According to the book, Lean tools can be used at any point in a project — for example, Belts often use them to clean up a messy, out-of-control process before applying Six Sigma statistics. True or False?",options:["True","False"],answer:0,hint:"Recall how the book places Lean tools inside DMAIC.",steps:[{title:"Key idea",body:"The book states that Lean tools can be used at any point, and that Belts use them to clean up out-of-control processes before applying Six Sigma."},{title:"Apply",body:"Removing obvious waste first (5S, standard work) reduces noise and outliers, so the statement is **True**."}],final:"Lean tools can be used anywhere in DMAIC → answer **A** (True)",whyWrong:["","False would restrict Lean tools to one phase; the book says they can be applied at any point."],bookRef:"Book p. 501"},{id:"sv-1-145",phase:1,topic:"1.4.3",qtype:"scenario",difficulty:2,stem:"A billing process is **fast** (bills issued within 24 hours) but **2.5%** of bills contain charge errors caused by variation in tariff set-up. Which approach should the Green Belt lead with?",options:["Lean flow tools, because speed is always the first priority","5S of the billing team’s shared drive","Kanban to pull bills through the process","Six Sigma tools to find and control the sources of variation behind the errors"],answer:3,hint:"Lean attacks waste and speed; Six Sigma attacks variation and defects.",steps:[{title:"Key idea",body:"Lean speeds flow by removing waste; Six Sigma reduces **variation and defects**. Lean Six Sigma picks the emphasis from the problem."},{title:"Apply",body:"Speed is already good; the problem is defects driven by variation, so lead with Six Sigma (measure, analyse X’s, control)."}],final:"Defect/variation problem → Six Sigma emphasis → answer **D**",whyWrong:["The process is already fast; more speed does not fix defects.","5S may help housekeeping but does not address the variation causing errors.","Kanban controls flow and WIP, which is not the problem here.",""],bookRef:"Book p. 502"},{id:"sv-1-146",phase:1,topic:"1.4.3",qtype:"concept",difficulty:2,stem:"The book says “a Six Sigma project is actually a **Kaizen**”, while breakthrough results are called **Kaikaku**. What is the difference?",options:["Kaizen is a tool for measuring waste; Kaikaku is a tool for measuring variation","Kaizen is used only in manufacturing; Kaikaku only in services","Kaizen is continual, step-by-step improvement; Kaikaku is radical, breakthrough change","Kaizen is led by Black Belts; Kaikaku by Green Belts"],answer:2,hint:"One is small and continual, the other large and sudden.",steps:[{title:"Key idea",body:"**Kaizen** = the philosophy of continual, incremental improvement. **Kaikaku** = radical or breakthrough improvement — the first focus of many Six Sigma projects."},{title:"Eliminate",body:"Neither is a measurement tool, both apply in any industry, and neither is tied to a belt level."}],final:"Kaizen = continual; Kaikaku = breakthrough → answer **C**",whyWrong:["Both are improvement philosophies, not measurement tools.","Both apply to manufacturing and services.","","Neither term is linked to a specific belt level."],bookRef:"Book p. 510"},{id:"sv-1-147",phase:1,topic:"1.4.4",qtype:"table",difficulty:2,stem:`A team maps observations in a service centre to the seven wastes:

| Observation | Waste assigned |
|---|---|
| Orders wait overnight for a credit decision | Waiting |
| Weekly reports printed that nobody reads | Overproduction |
| Technician walks to the store room for each spare part | Motion |
| Staff fix wrong addresses on returned bills | Inventory |

Which mapping is **wrong**?`,options:["Orders waiting for credit → Waiting","Unread weekly reports → Overproduction","Walking to the store room → Motion","Fixing wrong addresses on returned bills → Inventory"],answer:3,hint:"Fixing something that was done wrong is the waste of correction (defects/rework).",steps:[{title:"Key idea",body:"The book’s seven wastes: Correction, Overproduction, Processing, Conveyance, Inventory, Motion, Waiting."},{title:"Check each row",body:"Waiting, overproduction and motion are correctly assigned. Fixing wrong addresses is rework — **Correction**, not inventory."}],final:"Rework on returned bills = Correction → answer **D**",whyWrong:["Work sitting idle until a decision is made is waiting.","Producing reports nobody needs is overproduction.","Unneeded movement of people is motion.",""],bookRef:"Book p. 502"},{id:"sv-1-148",phase:1,topic:"1.4.4",qtype:"output",difficulty:2,stem:`During a one-week Gemba walk in a fulfilment centre, observers log **150** waste events:

\`\`\`
Tally for Discrete Variables: Waste type

Waste           Count  Percent
Waiting            46    30.67
Correction         31    20.67
Motion             22    14.67
Overprocessing     18    12.00
Inventory          14     9.33
Overproduction     10     6.67
Conveyance          9     6.00
     N=           150
\`\`\`

Which statement is supported by this output?`,options:["Waiting is the most frequently observed waste, at about 31% of events","Correction is the largest waste because it has 31 events, i.e. 31%","Overproduction can be ignored because it is rarely observed","The output proves Waiting costs more money than any other waste"],answer:0,hint:"Read Count and Percent correctly; frequency is not the same as cost.",steps:[{title:"Locate",body:"Waiting: 46 events. $$\\dfrac{46}{150}\\times 100=30.7\\%$$"},{title:"Apply",body:"Waiting is the most **frequent** waste. The tally gives counts, not costs; and overproduction often causes other wastes, so low frequency does not make it unimportant."}],final:"Waiting ≈ 31% of observations → answer **A**",whyWrong:["","Correction has 31 events, which is 20.7% of 150 — the count was read as a percentage.","Overproduction often drives inventory, waiting and conveyance; rare events can still matter.","The tally counts events; it says nothing about cost."],bookRef:"Book p. 502"},{id:"sv-1-149",phase:1,topic:"1.4.4",qtype:"true-false",difficulty:1,stem:"Re-checking a customer’s identity documents a third time, after two earlier checks already passed, is an example of the waste of **conveyance**. True or False?",options:["True","False"],answer:1,hint:"Conveyance = moving things; extra work the customer does not value = overprocessing.",steps:[{title:"Key idea",body:"Conveyance is unnecessary **transport** of materials, documents or information. Doing more work than the customer needs is **overprocessing**."},{title:"Apply",body:"A third identity check moves nothing — it is extra processing, so the statement is **False**."}],final:"It is overprocessing, not conveyance → answer **B** (False)",whyWrong:["True confuses moving things (conveyance) with doing extra work (overprocessing).",""],bookRef:"Book p. 502"},{id:"sv-1-150",phase:1,topic:"1.4.4",qtype:"not-except",difficulty:2,stem:"All of the following are among the **seven wastes** listed in the ICGB syllabus EXCEPT:",options:["Overproduction","Correction","Variation","Conveyance"],answer:2,hint:"The seven: Overproduction, Correction, Inventory, Motion, Overprocessing, Conveyance, Waiting.",steps:[{title:"Key idea",body:"The syllabus lists Overproduction, Correction, Inventory, Motion, Overprocessing, Conveyance and Waiting."},{title:"Find the intruder",body:"**Variation** is what Six Sigma attacks; it causes waste but is not one of the seven waste types."}],final:"Variation is not one of the seven wastes → answer **C**",whyWrong:["Overproduction is one of the seven wastes.","Correction (defects/rework) is one of the seven wastes.","","Conveyance (transport) is one of the seven wastes."],bookRef:"Syllabus 1.4.4"},{id:"sv-1-151",phase:1,topic:"1.4.4",qtype:"scenario",difficulty:1,stem:"Field engineers finish a job and then sit in the van for an average of **40 minutes** until dispatch assigns the next ticket. Which waste is this?",options:["Waiting","Motion","Inventory","Overprocessing"],answer:0,hint:"People or work idle, waiting for the next step or decision.",steps:[{title:"Key idea",body:"**Waiting** is idle time when people, equipment or work wait for the next step, information or decision."},{title:"Apply",body:"Engineers are idle until dispatch acts — waiting."}],final:"Idle until the next ticket → Waiting → answer **A**",whyWrong:["","Motion is unnecessary movement while working; here the engineers are idle.","Inventory is stored material or queued work, not idle people.","Overprocessing is doing more work than needed; here no work is being done."],bookRef:"Book p. 502"},{id:"sv-1-152",phase:1,topic:"1.4.4",qtype:"scenario",difficulty:3,stem:"A back office holds **2,800** unprocessed address-change requests. Some are weeks old; by the time they are handled, many customers have already called to chase them, and some requests are now out of date and must be re-checked. Which waste is the **visible symptom** that the team should reduce first to expose the other problems?",options:["Motion","Conveyance","Overprocessing","Inventory"],answer:3,hint:"A large queue of unprocessed work is the service form of stock, and it hides other problems.",steps:[{title:"Key idea",body:"In services, queues of unprocessed work are **inventory**. High inventory hides problems (like water hiding rocks) and creates follow-on waste: chasing calls and re-checking."},{title:"Apply",body:"Reducing the 2,800-request backlog exposes the underlying causes and cuts the secondary wastes."}],final:"Backlog of work = Inventory → answer **D**",whyWrong:["Motion is movement of people while working; the problem described is a queue.","Conveyance is moving documents or materials; nothing is being moved here.","The re-checks are overprocessing, but they are a consequence of the backlog, not the visible root.",""],bookRef:"Book pp. 502–503"},{id:"sv-1-153",phase:1,topic:"1.4.4",qtype:"scenario",difficulty:2,stem:"The sales team prints every enterprise quote, scans it into the document system, then emails the scan to the pricing team, who print it again to sign it and scan it back. Which waste is MOST prominent?",options:["Overprocessing","Overproduction","Waiting","Correction"],answer:0,hint:"Extra steps that add no value the customer would pay for.",steps:[{title:"Key idea",body:"Overprocessing = more work than the customer requires: extra prints, scans, re-formatting and approvals."},{title:"Apply",body:"Print → scan → email → print → scan adds steps without changing form, fit or function of the quote — overprocessing (a digital signature would remove most of it)."}],final:"Redundant print/scan cycles → Overprocessing → answer **A**",whyWrong:["","Overproduction is making more output than needed or before it is needed; here one quote is made.","Waiting may occur, but the scenario describes unnecessary steps.","Correction is fixing errors; nothing here is being fixed."],bookRef:"Book p. 117"},{id:"sv-1-154",phase:1,topic:"1.4.4",qtype:"concept",difficulty:2,stem:"The syllabus introduction lists **eight** kinds of waste, while topic 1.4.4 lists seven. Which waste is added in the eight-waste list?",options:["Variation","Overburden","Unevenness","Non-utilised talent"],answer:3,hint:"The extra waste is about people’s skills and ideas.",steps:[{title:"Key idea",body:"The eight-waste list (often remembered as DOWNTIME) adds **non-utilised talent** — not using people’s skills, knowledge and ideas."},{title:"Eliminate",body:"Overburden (muri) and unevenness (mura) are separate Toyota concepts, not the eighth muda; variation is the Six Sigma target."}],final:"Eighth waste = non-utilised talent → answer **D**",whyWrong:["Variation is the focus of Six Sigma, not a waste category.","Overburden is muri, a separate concept from the eight muda.","Unevenness is mura, a separate concept from the eight muda.",""],bookRef:"Syllabus p. 2"},{id:"sv-1-155",phase:1,topic:"1.4.5",qtype:"table",difficulty:2,stem:`A NOC team uses the book’s frequency-of-use guide to store items:

| Frequency of use | Class | Arm’s reach | Local location | Remote location |
|---|---|---|---|---|
| Daily or several times a day | A | YES | MAYBE | NO |
| Weekly | B | MAYBE | YES | NO |
| Monthly or quarterly | C | NO | NO | YES |

A fibre splicing kit is used **about once a week**. Where should it be stored?`,options:["In a local location, such as a cabinet in the same room","On the work surface within arm’s reach","In a remote store a few minutes’ walk away","It should be disposed of in the Sort step"],answer:0,hint:"Read the row for weekly use and find the YES.",steps:[{title:"Locate",body:"Weekly use = class **B**; the YES is under **local location**."},{title:"Apply",body:"The book says B items should not sit on the work surface but within easy walking distance — e.g. a nearby cabinet in the same room."}],final:"Weekly (B) item → local location → answer **A**",whyWrong:["","Arm’s reach is only “MAYBE” for B items; it is meant for daily (A) items.","Remote storage is for monthly or quarterly (C) items.","The kit is clearly useful, so Sort keeps it."],bookRef:"Book p. 506"},{id:"sv-1-156",phase:1,topic:"1.4.5",qtype:"sequence",difficulty:3,stem:`The book’s method for **Sorting** an equipment room includes:

- **P** Dispose of items that turn out not to be used during the period
- **Q** Keep “unknown” items where they are for a set period and monitor their use
- **R** Classify each item as useful, useless or unknown
- **S** Dispose of useless items immediately

Which order follows the book’s method?`,options:["Q → R → S → P","S → R → Q → P","R → S → Q → P","R → Q → P → S"],answer:2,hint:"Classify first; act on the clear cases at once; give the unclear ones a trial period.",steps:[{title:"Key idea",body:"The book: classify each item as **useful, useless or unknown**; dispose of useless items immediately; keep unknown items for a predetermined period; if unused, dispose of them."},{title:"Apply",body:"That is R → S → Q → P."}],final:"Classify → dispose useless → monitor unknown → dispose unused → answer **C**",whyWrong:["Items cannot be monitored as “unknown” before they are classified.","Useless items cannot be identified before classification.","","Useless items are disposed of immediately, not after the monitoring period."],bookRef:"Book p. 505"},{id:"sv-1-157",phase:1,topic:"1.4.5",qtype:"scenario",difficulty:1,stem:"A team paints the outline of each test instrument on a wall board so everyone can see where each tool belongs and which one is missing. Which 5S step is this?",options:["Sort","Shine","Self-discipline (Sustain)","Straighten (Set in order)"],answer:3,hint:"A place for everything and everything in its place.",steps:[{title:"Key idea",body:"**Straighten** arranges needed items so they are easy to find and use — the book lists labels, tape, floor markings and **shadow outlines**."},{title:"Apply",body:"A shadow board gives every tool a visible home, so this is Straighten."}],final:"Shadow board → Straighten → answer **D**",whyWrong:["Sort removes unneeded items; it does not assign locations.","Shine is cleaning and inspecting.","Sustain builds habits and audits after the first steps are in place.",""],bookRef:"Book p. 506"},{id:"sv-1-158",phase:1,topic:"1.4.5",qtype:"scenario",difficulty:2,stem:"While cleaning server racks each week, an engineer notices an oil-like stain under a cooling unit and logs a fault before it fails. Which benefit of **Shine** does this show?",options:["A clean workplace helps reveal abnormal conditions early","Cleaning frees up storage space","Cleaning removes the need for preventive maintenance","Shine sets the standard for where tools are kept"],answer:0,hint:"Shine = clean and inspect.",steps:[{title:"Key idea",body:"The book says a clean workplace **helps identify abnormal conditions** — cleaning is a form of inspection."},{title:"Apply",body:"Spotting the stain during cleaning lets the team act before a failure."}],final:"Shine exposes abnormalities → answer **A**",whyWrong:["","Freeing space is the benefit of Sort.","Shine supports maintenance; it does not replace it.","Assigning tool locations is Straighten."],bookRef:"Book p. 507"},{id:"sv-1-159",phase:1,topic:"1.4.5",qtype:"concept",difficulty:2,stem:"Which statement BEST describes the fifth S, **Self-discipline (Sustain)**?",options:["Painting lines and colour-coding areas","Removing items that are not needed","Cleaning the workplace every day","Building 5S into daily habits through schedules, checklists, audits and commitment"],answer:3,hint:"The book: without sustaining, the workplace reverts.",steps:[{title:"Key idea",body:"Sustain is the **discipline and commitment** that keep the other four S’s alive — schedules, checklists, audits and empowered teams."},{title:"Eliminate",body:"Painted lines are Standardize visual controls; removing items is Sort; daily cleaning is Shine."}],final:"Sustain = habits, checklists, audits, commitment → answer **D**",whyWrong:["Painted lines and colour-coding are Standardize visual controls.","Removing unneeded items is Sort.","Cleaning is Shine.",""],bookRef:"Book p. 508"},{id:"sv-1-160",phase:1,topic:"1.4.5",qtype:"concept",difficulty:3,stem:"According to the book, which sign in a Six Sigma project suggests that **5S is needed**?",options:["Outliers in the project metric, or a loss of the initial gains after improvement","A Gage R&R study with ndc above 5","A Pareto chart with a clear vital few","A charter that has been signed by the Champion"],answer:0,hint:"Messy, disorganised work shows up as unexplained spikes and slipping results.",steps:[{title:"Key idea",body:"The book lists **outliers in the project metric** and **loss of initial gains** as signs that 5S (and other Lean controls) are needed."},{title:"Apply",body:"Disorder creates random special causes (outliers) and lets processes drift back; 5S stabilises the workplace so gains hold."}],final:"Outliers or lost gains → 5S needed → answer **A**",whyWrong:["","ndc above 5 means the measurement system is adequate — not a 5S signal.","A clear vital few is a good Pareto result, not a sign of disorder.","A signed charter is a normal Define milestone."],bookRef:"Book p. 513"}];export{e as items};
